const t="-SOVLf-g0ZM",n="-SOVLf-g0ZM",e="Slow Listening & Shadowing for Beginners (A1- A2) | Motivation to Learn English | English Podcast",i="English Unleashed: The Podcast",r="A1",a="Podcast tốc độ chậm",d=2,h=1435,s="auto",o=JSON.parse(`[{"start":0.32,"end":5.04,"text":"Hello my friends and welcome back to English Unleashed.","words":[["Hello",0.32],["my",0.72],["friends",1.04],["and",1.44],["welcome",1.76],["back",2.24],["to",2.64],["English",3.04],["Unleashed.",3.84]],"ipa":"/həˈloʊ maɪ frɛndz ənd ˈwɛlkəm bæk tu ˈɪŋɡlɪʃ ənˈliʃt/","vi":"Xin chào các bạn của tôi và chào mừng trở lại với English Unleashed."},{"start":5.04,"end":9.92,"text":"I'm Tom and I'm so happy you are here today.","words":[["I'm",5.04],["Tom",5.36],["and",6.16],["I'm",6.48],["so",6.8],["happy",7.2],["you",7.84],["are",8.16],["here",8.4],["today.",8.72]],"ipa":"/aɪm tɑm ənd aɪm soʊ ˈhæpi ju ɑr hir təˈdeɪ/","vi":"Tôi là Tom và tôi rất vui vì bạn có mặt ở đây hôm nay."},{"start":9.92,"end":17.52,"text":"In today's episode, I will talk about motivation in language learning.","words":[["In",9.92],["today's",10.16],["episode,",10.8],["I",11.92],["will",12.16],["talk",12.4],["about",12.72],["motivation",13.36],["in",14.48],["language",14.88],["learning.",15.68]],"ipa":"/ɪn təˈdeɪz ˈɛpəˌsoʊd aɪ wɪl tɔk əˈbaʊt ˌmoʊtəˈveɪʃən ɪn ˈlæŋɡwədʒ ˈlɝnɪŋ/","vi":"Trong tập hôm nay, tôi sẽ nói về động lực trong việc học ngôn ngữ."},{"start":17.52,"end":31.52,"text":"That means how to stay strong, how to keep going, how to enjoy the process of learning English even when it feels hard.","words":[["That",17.52],["means",17.84],["how",18.64],["to",18.96],["stay",19.28],["strong,",19.92],["how",21.76],["to",22],["keep",22.32],["going,",22.96],["how",24.72],["to",24.96],["enjoy",25.2],["the",25.68],["process",26.08],["of",26.56],["learning",26.88],["English",27.28],["even",28.24],["when",28.64],["it",29.2],["feels",29.6],["hard.",30.4]],"ipa":"/ðæt minz haʊ tu steɪ strɔŋ haʊ tu kip ˈɡoʊɪŋ haʊ tu ˌɛnˈdʒɔɪ ðə ˈprɑˌsɛs ʌv ˈlɝnɪŋ ˈɪŋɡlɪʃ ˈivɪn wɛn ɪt filz hɑrd/","vi":"Điều đó có nghĩa là làm thế nào để luôn mạnh mẽ, làm thế nào để tiếp tục, làm thế nào để tận hưởng quá trình học tiếng Anh ngay cả khi cảm thấy khó khăn."},{"start":31.52,"end":35.36,"text":"In this podcast, I speak slowly.","words":[["In",31.52],["this",31.76],["podcast,",32],["I",32.88],["speak",33.28],["slowly.",33.92]],"ipa":"/ɪn ðɪs ˈpɔdˌkæst aɪ spik ˈsloʊli/","vi":"Trong podcast này, tôi nói chậm."},{"start":35.36,"end":44.08,"text":"I use simple words and I repeat key ideas so you can understand easily.","words":[["I",35.36],["use",35.76],["simple",36.4],["words",36.88],["and",38.08],["I",38.4],["repeat",38.64],["key",39.28],["ideas",39.68],["so",40.64],["you",40.96],["can",41.2],["understand",41.36],["easily.",42.32]],"ipa":"/aɪ jus ˈsɪmpəl wɝdz ənd aɪ rɪˈpit ki aɪˈdiəz soʊ ju kæn ˌʌndərˈstænd ˈizəli/","vi":"Tôi sử dụng những từ đơn giản và lặp lại những ý chính để bạn có thể hiểu dễ dàng."},{"start":44.08,"end":49.44,"text":"You can listen, repeat and speak with me.","words":[["You",44.08],["can",44.4],["listen,",44.64],["repeat",46.08],["and",47.12],["speak",47.84],["with",48.16],["me.",48.48]],"ipa":"/ju kæn ˈlɪsən rɪˈpit ənd spik wɪð mi/","vi":"Bạn có thể nghe, lặp lại và nói chuyện với tôi."},{"start":49.44,"end":54.24,"text":"You can practice English step by step.","words":[["You",49.44],["can",49.68],["practice",50],["English",50.56],["step",51.6],["by",52.16],["step.",52.96]],"ipa":"/ju kæn ˈpræktəs ˈɪŋɡlɪʃ stɛp baɪ stɛp/","vi":"Bạn có thể thực hành tiếng Anh từng bước một."},{"start":54.24,"end":57.04,"text":"This is called shadowing.","words":[["This",54.24],["is",54.48],["called",54.72],["shadowing.",55.44]],"ipa":"/ðɪs ɪz kɔld ˈʃædoʊɪŋ/","vi":"Điều này được gọi là đổ bóng."},{"start":57.04,"end":61.44,"text":"You listen, then repeat after me.","words":[["You",57.04],["listen,",57.36],["then",58.56],["repeat",58.96],["after",59.52],["me.",60]],"ipa":"/ju ˈlɪsən ðɛn rɪˈpit ˈæftər mi/","vi":"Bạn nghe rồi lặp lại theo tôi nhé."},{"start":61.44,"end":64.56,"text":"So, are you ready?","words":[["So,",61.44],["are",62.48],["you",62.72],["ready?",62.96]],"ipa":"/soʊ ɑr ju ˈrɛdi/","vi":"Vì vậy, bạn đã sẵn sàng chưa?"},{"start":64.56,"end":75.44,"text":"Take a deep breath, relax, and let's begin together. All right.","words":[["Take",64.56],["a",64.8],["deep",65.04],["breath,",65.36],["relax,",67.04],["and",68.64],["let's",68.96],["begin",69.44],["together.",70.24],["All",74.16],["right.",74.32]],"ipa":"/teɪk ə dip brɛθ rɪˈlæks ənd lɛts bɪˈɡɪn təˈɡɛðər ɔl raɪt/","vi":"Hãy hít một hơi thật sâu, thư giãn và cùng nhau bắt đầu. Được rồi."},{"start":75.44,"end":80.48,"text":"Learning English is not easy and that's okay.","words":[["Learning",75.44],["English",75.84],["is",76.48],["not",76.8],["easy",77.36],["and",78.16],["that's",78.48],["okay.",78.96]],"ipa":"/ˈlɝnɪŋ ˈɪŋɡlɪʃ ɪz nɑt ˈizi ənd ðæts ˌoʊˈkeɪ/","vi":"Học tiếng Anh không hề dễ dàng và điều đó không sao cả."},{"start":80.48,"end":83.76,"text":"It's normal to feel tired.","words":[["It's",80.48],["normal",80.88],["to",81.52],["feel",81.84],["tired.",82.32]],"ipa":"/ɪts ˈnɔrməl tu fil ˈtaɪərd/","vi":"Cảm thấy mệt mỏi là điều bình thường."},{"start":83.76,"end":87.44,"text":"It's normal to feel slow.","words":[["It's",83.76],["normal",84.08],["to",84.72],["feel",85.04],["slow.",85.76]],"ipa":"/ɪts ˈnɔrməl tu fil sloʊ/","vi":"Cảm giác chậm là điều bình thường."},{"start":87.44,"end":90.24,"text":"But you are not alone.","words":[["But",87.44],["you",87.68],["are",87.92],["not",88.08],["alone.",88.56]],"ipa":"/bʌt ju ɑr nɑt əˈloʊn/","vi":"Nhưng bạn không đơn độc."},{"start":90.24,"end":95.92,"text":"Everyone who learns a new language needs time.","words":[["Everyone",90.24],["who",90.88],["learns",91.2],["a",91.6],["new",91.92],["language",92.24],["needs",93.28],["time.",94.24]],"ipa":"/ˈɛvriˌwʌn hu lɝnz ə nu ˈlæŋɡwədʒ nidz taɪm/","vi":"Mọi người học một ngôn ngữ mới đều cần có thời gian."},{"start":95.92,"end":102.64,"text":"You need time to listen, time to practice.","words":[["You",95.92],["need",96.16],["time",96.8],["to",97.52],["listen,",97.84],["time",99.44],["to",100.32],["practice.",100.72]],"ipa":"/ju nid taɪm tu ˈlɪsən taɪm tu ˈpræktəs/","vi":"Bạn cần thời gian để lắng nghe, thời gian để thực hành."},{"start":102.64,"end":106.64,"text":"You need time to understand.","words":[["You",102.64],["need",102.88],["time",103.44],["to",104.32],["understand.",104.72]],"ipa":"/ju nid taɪm tu ˌʌndərˈstænd/","vi":"Bạn cần thời gian để hiểu."},{"start":106.64,"end":112.72,"text":"You need time to grow, to improve.","words":[["You",106.64],["need",106.88],["time",107.2],["to",108.16],["grow,",108.48],["to",110.08],["improve.",110.4]],"ipa":"/ju nid taɪm tu ɡroʊ tu ˌɪmˈpruv/","vi":"Bạn cần thời gian để phát triển, để cải thiện."},{"start":112.72,"end":116.56,"text":"Some days learning feels fun.","words":[["Some",112.72],["days",113.04],["learning",113.84],["feels",114.4],["fun.",115.12]],"ipa":"/sʌm deɪz ˈlɝnɪŋ filz fʌn/","vi":"Một số ngày học tập cảm thấy thú vị."},{"start":116.56,"end":119.92,"text":"Some days it feels hard.","words":[["Some",116.56],["days",116.8],["it",117.76],["feels",118.08],["hard.",118.8]],"ipa":"/sʌm deɪz ɪt filz hɑrd/","vi":"Một số ngày nó cảm thấy khó khăn."},{"start":119.92,"end":122.56,"text":"That's part of the journey.","words":[["That's",119.92],["part",120.32],["of",120.64],["the",120.8],["journey.",121.12]],"ipa":"/ðæts pɑrt ʌv ðə ˈdʒɝni/","vi":"Đó là một phần của cuộc hành trình."},{"start":122.56,"end":127.12,"text":"On good days, enjoy your progress.","words":[["On",122.56],["good",122.88],["days,",123.12],["enjoy",124.16],["your",124.8],["progress.",125.2]],"ipa":"/ɑn ɡʊd deɪz ˌɛnˈdʒɔɪ jɔr ˈprɑˌɡrɛs/","vi":"Vào những ngày tốt lành, hãy tận hưởng sự tiến bộ của bạn."},{"start":127.12,"end":131.68,"text":"On bad days, just keep going.","words":[["On",127.12],["bad",127.44],["days,",127.76],["just",129.12],["keep",129.52],["going.",130]],"ipa":"/ɑn bæd deɪz dʒʌst kip ˈɡoʊɪŋ/","vi":"Vào những ngày tồi tệ, hãy cứ tiếp tục."},{"start":131.68,"end":136.88,"text":"Even small steps are good steps.","words":[["Even",131.68],["small",132.32],["steps",132.88],["are",134.16],["good",134.8],["steps.",135.44]],"ipa":"/ˈivɪn smɔl stɛps ɑr ɡʊd stɛps/","vi":"Ngay cả những bước nhỏ cũng là những bước tốt."},{"start":136.88,"end":140,"text":"You don't need to be perfect.","words":[["You",136.88],["don't",137.2],["need",137.44],["to",137.68],["be",137.92],["perfect.",138.24]],"ipa":"/ju doʊnt nid tu bi pərˈfɛkt/","vi":"Bạn không cần phải hoàn hảo."},{"start":140,"end":143.68,"text":"You don't need to speak fast.","words":[["You",140],["don't",140.32],["need",140.64],["to",140.88],["speak",141.2],["fast.",141.84]],"ipa":"/ju doʊnt nid tu spik fæst/","vi":"Bạn không cần phải nói nhanh."},{"start":143.68,"end":147.28,"text":"You don't need to know every word.","words":[["You",143.68],["don't",143.92],["need",144.32],["to",144.48],["know",144.8],["every",145.2],["word.",145.76]],"ipa":"/ju doʊnt nid tu noʊ ˈɛvəri wɝd/","vi":"Bạn không cần phải biết từng từ."},{"start":147.28,"end":150.56,"text":"You just need to try.","words":[["You",147.28],["just",147.6],["need",148.16],["to",148.4],["try.",148.8]],"ipa":"/ju dʒʌst nid tu traɪ/","vi":"Bạn chỉ cần cố gắng."},{"start":150.56,"end":159.36,"text":"You just need to keep going slowly, gently, step by step.","words":[["You",150.56],["just",150.88],["need",151.12],["to",151.36],["keep",151.68],["going",152.24],["slowly,",153.84],["gently,",155.44],["step",156.96],["by",157.44],["step.",158.16]],"ipa":"/ju dʒʌst nid tu kip ˈɡoʊɪŋ ˈsloʊli ˈdʒɛntli stɛp baɪ stɛp/","vi":"Bạn chỉ cần tiếp tục đi chậm rãi, nhẹ nhàng, từng bước một."},{"start":159.36,"end":161.12,"text":"You are learning.","words":[["You",159.36],["are",159.6],["learning.",159.84]],"ipa":"/ju ɑr ˈlɝnɪŋ/","vi":"Bạn đang học."},{"start":161.12,"end":167.76,"text":"You are doing something difficult and you are doing it well.","words":[["You",161.12],["are",161.44],["doing",161.84],["something",162.32],["difficult",162.88],["and",164.32],["you",164.72],["are",164.96],["doing",165.44],["it",165.76],["well.",166.32]],"ipa":"/ju ɑr ˈduɪŋ ˈsʌmθɪŋ ˈdɪfəkəlt ənd ju ɑr ˈduɪŋ ɪt wɛl/","vi":"Bạn đang làm một việc gì đó khó khăn và bạn đang làm tốt việc đó."},{"start":167.76,"end":172.08,"text":"Learning English is like climbing a mountain.","words":[["Learning",167.76],["English",168.16],["is",169.2],["like",169.6],["climbing",170.16],["a",170.72],["mountain.",170.96]],"ipa":"/ˈlɝnɪŋ ˈɪŋɡlɪʃ ɪz laɪk ˈklaɪmɪŋ ə ˈmaʊntən/","vi":"Học tiếng Anh giống như leo núi."},{"start":172.08,"end":180.72,"text":"Sometimes it's easy, sometimes it's hard, sometimes you want to stop.","words":[["Sometimes",172.08],["it's",172.88],["easy,",173.28],["sometimes",174.56],["it's",175.52],["hard,",176],["sometimes",177.52],["you",178.4],["want",178.8],["to",179.04],["stop.",179.44]],"ipa":"/səmˈtaɪmz ɪts ˈizi səmˈtaɪmz ɪts hɑrd səmˈtaɪmz ju wɑnt tu stɑp/","vi":"Đôi khi dễ dàng, đôi khi khó khăn, đôi khi bạn muốn dừng lại."},{"start":180.72,"end":188.48,"text":"But when you look back, you will see you have already come so far.","words":[["But",180.72],["when",180.88],["you",181.12],["look",181.36],["back,",181.6],["you",182.72],["will",182.96],["see",183.2],["you",183.92],["have",184.24],["already",184.64],["come",185.28],["so",186.08],["far.",186.72]],"ipa":"/bʌt wɛn ju lʊk bæk ju wɪl si ju hæv ɔlˈrɛdi kʌm soʊ fɑr/","vi":"Nhưng khi nhìn lại, bạn sẽ thấy mình đã đi được rất xa."},{"start":188.48,"end":191.36,"text":"You have learned new words.","words":[["You",188.48],["have",188.8],["learned",188.96],["new",189.52],["words.",189.92]],"ipa":"/ju hæv lɝnd nu wɝdz/","vi":"Bạn đã học được từ mới."},{"start":191.36,"end":193.36,"text":"You have listened.","words":[["You",191.36],["have",191.6],["listened.",191.92]],"ipa":"/ju hæv ˈlɪsənd/","vi":"Bạn đã lắng nghe."},{"start":193.36,"end":195.68,"text":"You have practiced.","words":[["You",193.36],["have",193.6],["practiced.",194.16]],"ipa":"/ju hæv ˈpræktəst/","vi":"Bạn đã thực hành."},{"start":195.68,"end":198.24,"text":"You have improved.","words":[["You",195.68],["have",196],["improved.",196.48]],"ipa":"/ju hæv ˌɪmˈpruvd/","vi":"Bạn đã tiến bộ."},{"start":198.24,"end":205.2,"text":"Even if you don't see it yet, you are not at the bottom anymore.","words":[["Even",198.24],["if",198.56],["you",199.12],["don't",199.44],["see",200],["it",200.24],["yet,",200.56],["you",201.84],["are",202.08],["not",202.32],["at",202.72],["the",202.96],["bottom",203.2],["anymore.",203.68]],"ipa":"/ˈivɪn ɪf ju doʊnt si ɪt jɛt ju ɑr nɑt æt ðə ˈbɑtəm ˌɛniˈmɔr/","vi":"Ngay cả khi bạn chưa nhìn thấy nó, bạn cũng không còn ở phía dưới nữa."},{"start":205.2,"end":207.68,"text":"You are climbing.","words":[["You",205.2],["are",205.52],["climbing.",206.08]],"ipa":"/ju ɑr ˈklaɪmɪŋ/","vi":"Bạn đang leo núi."},{"start":207.68,"end":211.2,"text":"You are getting stronger.","words":[["You",207.68],["are",207.92],["getting",208.56],["stronger.",209.44]],"ipa":"/ju ɑr ˈɡɛtɪŋ ˈstrɔŋər/","vi":"Bạn đang trở nên mạnh mẽ hơn."},{"start":211.2,"end":213.44,"text":"So don't give up.","words":[["So",211.2],["don't",211.92],["give",212.24],["up.",212.48]],"ipa":"/soʊ doʊnt ɡɪv ʌp/","vi":"Vì vậy, đừng bỏ cuộc."},{"start":213.44,"end":216.08,"text":"Some people learn fast.","words":[["Some",213.44],["people",213.76],["learn",214.16],["fast.",214.56]],"ipa":"/sʌm ˈpipəl lɝn fæst/","vi":"Một số người học nhanh."},{"start":216.08,"end":219.68,"text":"Some people learn slow.","words":[["Some",216.08],["people",216.4],["learn",216.96],["slow.",217.76]],"ipa":"/sʌm ˈpipəl lɝn sloʊ/","vi":"Một số người học chậm."},{"start":219.68,"end":226.88,"text":"But all learners need one thing. Motivation.","words":[["But",219.68],["all",220],["learners",220.32],["need",221.44],["one",222.32],["thing.",222.96],["Motivation.",224.72]],"ipa":"/bʌt ɔl ˈlɝnərz nid wʌn θɪŋ ˌmoʊtəˈveɪʃən/","vi":"Nhưng tất cả người học đều cần một điều. Động lực."},{"start":226.88,"end":230.48,"text":"Motivation is not magic.","words":[["Motivation",226.88],["is",228],["not",228.4],["magic.",228.8]],"ipa":"/ˌmoʊtəˈveɪʃən ɪz nɑt ˈmædʒɪk/","vi":"Động lực không phải là phép thuật."},{"start":230.48,"end":233.12,"text":"It's not always loud.","words":[["It's",230.48],["not",230.8],["always",231.12],["loud.",231.92]],"ipa":"/ɪts nɑt ˈɔlˌweɪz laʊd/","vi":"Nó không phải lúc nào cũng ồn ào."},{"start":233.12,"end":236.4,"text":"Sometimes it's quiet.","words":[["Sometimes",233.12],["it's",234.16],["quiet.",234.8]],"ipa":"/səmˈtaɪmz ɪts ˈkwaɪət/","vi":"Đôi khi nó yên tĩnh."},{"start":236.4,"end":243.04,"text":"It's the little voice that says, \\"Try again. Don't stop.","words":[["It's",236.4],["the",236.72],["little",237.04],["voice",237.36],["that",237.84],["says,",238.16],["\\"Try",239.36],["again.",239.84],["Don't",241.28],["stop.",241.68]],"ipa":"/ɪts ðə ˈlɪtəl vɔɪs ðæt sɛz traɪ əˈɡɛn doʊnt stɑp/","vi":"Đó là một giọng nói nhỏ nói: \\"Thử lại đi. Đừng dừng lại."},{"start":243.04,"end":246.4,"text":"Just do one more minute.","words":[["Just",243.04],["do",243.36],["one",244],["more",244.32],["minute.",244.64]],"ipa":"/dʒʌst du wʌn mɔr ˈmɪnət/","vi":"Chỉ cần làm thêm một phút nữa thôi."},{"start":246.4,"end":248.24,"text":"And that's enough.","words":[["And",246.4],["that's",246.64],["enough.",246.96]],"ipa":"/ənd ðæts ɪˈnʌf/","vi":"Và thế là đủ."},{"start":248.24,"end":253.6,"text":"If you feel tired, rest, then come back.","words":[["If",248.24],["you",248.48],["feel",248.72],["tired,",248.96],["rest,",250.16],["then",251.36],["come",251.92],["back.",252.16]],"ipa":"/ɪf ju fil ˈtaɪərd rɛst ðɛn kʌm bæk/","vi":"Nếu thấy mệt thì nghỉ ngơi rồi quay lại."},{"start":253.6,"end":259.2,"text":"If you feel confused, breathe, then try again.","words":[["If",253.6],["you",253.92],["feel",254.08],["confused,",254.4],["breathe,",255.84],["then",257.28],["try",257.6],["again.",257.92]],"ipa":"/ɪf ju fil kənfˈjuzd brið ðɛn traɪ əˈɡɛn/","vi":"Nếu bạn cảm thấy bối rối, hãy thở và thử lại."},{"start":259.2,"end":261.84,"text":"You don't need a perfect plan.","words":[["You",259.2],["don't",259.44],["need",259.68],["a",259.92],["perfect",260.24],["plan.",260.8]],"ipa":"/ju doʊnt nid ə pərˈfɛkt plæn/","vi":"Bạn không cần một kế hoạch hoàn hảo."},{"start":261.84,"end":266.96,"text":"You just need to return again and again.","words":[["You",261.84],["just",262.08],["need",262.64],["to",262.88],["return",263.2],["again",264.56],["and",265.04],["again.",265.36]],"ipa":"/ju dʒʌst nid tu rɪˈtɝn əˈɡɛn ənd əˈɡɛn/","vi":"Bạn chỉ cần quay lại nhiều lần."},{"start":266.96,"end":273.36,"text":"So ask yourself, why do I want to learn English?","words":[["So",266.96],["ask",267.52],["yourself,",267.92],["why",269.76],["do",270],["I",270.24],["want",270.48],["to",270.72],["learn",270.96],["English?",271.52]],"ipa":"/soʊ æsk jərˈsɛlf waɪ du aɪ wɑnt tu lɝn ˈɪŋɡlɪʃ/","vi":"Vậy hãy tự hỏi, tại sao tôi lại muốn học tiếng Anh?"},{"start":273.36,"end":276.16,"text":"Maybe it's for your job.","words":[["Maybe",273.36],["it's",273.76],["for",274.08],["your",274.32],["job.",274.64]],"ipa":"/ˈmeɪbi ɪts fɔr jɔr dʒɑb/","vi":"Có lẽ nó dành cho công việc của bạn."},{"start":276.16,"end":279.28,"text":"Maybe it's to travel.","words":[["Maybe",276.16],["it's",276.8],["to",277.12],["travel.",277.44]],"ipa":"/ˈmeɪbi ɪts tu ˈtrævəl/","vi":"Có lẽ đó là để đi du lịch."},{"start":279.28,"end":283.28,"text":"Maybe it's just because you enjoy it.","words":[["Maybe",279.28],["it's",279.68],["just",280.08],["because",280.4],["you",281.04],["enjoy",281.36],["it.",281.76]],"ipa":"/ˈmeɪbi ɪts dʒʌst bɪˈkɔz ju ˌɛnˈdʒɔɪ ɪt/","vi":"Có lẽ đó chỉ là vì bạn thích nó."},{"start":283.28,"end":287.2,"text":"Your reason is important.","words":[["Your",283.28],["reason",283.68],["is",284.88],["important.",285.2]],"ipa":"/jɔr ˈrizən ɪz ˌɪmˈpɔrtənt/","vi":"Lý do của bạn là quan trọng."},{"start":287.2,"end":291.04,"text":"Your reason is strong.","words":[["Your",287.2],["reason",287.6],["is",288.56],["strong.",289.28]],"ipa":"/jɔr ˈrizən ɪz strɔŋ/","vi":"Lý do của bạn rất mạnh mẽ."},{"start":291.04,"end":296.16,"text":"Your reason will help you stay motivated.","words":[["Your",291.04],["reason",291.36],["will",292.24],["help",292.64],["you",292.88],["stay",293.2],["motivated.",293.92]],"ipa":"/jɔr ˈrizən wɪl hɛlp ju steɪ ˈmoʊtəˌveɪtəd/","vi":"Lý do của bạn sẽ giúp bạn luôn có động lực."},{"start":296.16,"end":302.8,"text":"Remember, every day you practice English, you are moving forward.","words":[["Remember,",296.16],["every",297.28],["day",297.68],["you",298],["practice",298.32],["English,",298.96],["you",299.84],["are",300.16],["moving",300.48],["forward.",301.36]],"ipa":"/rɪˈmɛmbər ˈɛvəri deɪ ju ˈpræktəs ˈɪŋɡlɪʃ ju ɑr ˈmuvɪŋ ˈfɔrwərd/","vi":"Hãy nhớ rằng, mỗi ngày bạn luyện tập tiếng Anh, bạn đang tiến về phía trước."},{"start":302.8,"end":306.72,"text":"Even if it's just five minutes.","words":[["Even",302.8],["if",303.12],["it's",303.68],["just",304.08],["five",304.72],["minutes.",305.12]],"ipa":"/ˈivɪn ɪf ɪts dʒʌst faɪv ˈmɪnəts/","vi":"Dù chỉ là năm phút thôi."},{"start":306.72,"end":310.64,"text":"Even if it's just listening.","words":[["Even",306.72],["if",306.96],["it's",307.92],["just",308.32],["listening.",308.8]],"ipa":"/ˈivɪn ɪf ɪts dʒʌst ˈlɪsənɪŋ/","vi":"Dù chỉ là nghe thôi."},{"start":310.64,"end":316.24,"text":"Even if it's just trying, you are growing.","words":[["Even",310.64],["if",310.88],["it's",311.84],["just",312.24],["trying,",313.04],["you",314.24],["are",314.56],["growing.",314.8]],"ipa":"/ˈivɪn ɪf ɪts dʒʌst ˈtraɪɪŋ ju ɑr ˈɡroʊɪŋ/","vi":"Ngay cả khi chỉ cố gắng, bạn vẫn đang trưởng thành."},{"start":316.24,"end":318.96,"text":"You are becoming better.","words":[["You",316.24],["are",316.48],["becoming",316.8],["better.",317.52]],"ipa":"/ju ɑr bɪˈkʌmɪŋ ˈbɛtər/","vi":"Bạn đang trở nên tốt hơn."},{"start":318.96,"end":324.16,"text":"And you should be proud of yourself.","words":[["And",318.96],["you",319.68],["should",320.08],["be",320.4],["proud",321.04],["of",321.52],["yourself.",321.84]],"ipa":"/ənd ju ʃʊd bi praʊd ʌv jərˈsɛlf/","vi":"Và bạn nên tự hào về chính mình."},{"start":324.16,"end":329.68,"text":"You are doing something many people are afraid to do.","words":[["You",324.16],["are",324.48],["doing",324.64],["something",325.12],["many",325.92],["people",326.4],["are",326.96],["afraid",327.2],["to",327.92],["do.",328.24]],"ipa":"/ju ɑr ˈduɪŋ ˈsʌmθɪŋ ˈmɛni ˈpipəl ɑr əˈfreɪd tu du/","vi":"Bạn đang làm điều mà nhiều người sợ phải làm."},{"start":329.68,"end":333.76,"text":"You are learning a new language.","words":[["You",329.68],["are",330.08],["learning",330.64],["a",331.28],["new",331.6],["language.",332]],"ipa":"/ju ɑr ˈlɝnɪŋ ə nu ˈlæŋɡwədʒ/","vi":"Bạn đang học một ngôn ngữ mới."},{"start":333.76,"end":338.08,"text":"You are opening a door to the world.","words":[["You",333.76],["are",334.08],["opening",334.56],["a",335.04],["door",335.36],["to",336],["the",336.24],["world.",336.56]],"ipa":"/ju ɑr ˈoʊpənɪŋ ə dɔr tu ðə wɝld/","vi":"Bạn đang mở một cánh cửa đến với thế giới."},{"start":338.08,"end":341.44,"text":"And that takes courage.","words":[["And",338.08],["that",338.32],["takes",339.04],["courage.",339.84]],"ipa":"/ənd ðæt teɪks ˈkɝədʒ/","vi":"Và điều đó cần có sự can đảm."},{"start":341.44,"end":350.96,"text":"So stay motivated, stay patient, stay kind to yourself.","words":[["So",341.44],["stay",342.72],["motivated,",343.12],["stay",344.72],["patient,",345.2],["stay",346.96],["kind",347.52],["to",348.4],["yourself.",348.72]],"ipa":"/soʊ steɪ ˈmoʊtəˌveɪtəd steɪ ˈpeɪʃənt steɪ kaɪnd tu jərˈsɛlf/","vi":"Vì vậy, hãy luôn có động lực, hãy kiên nhẫn, hãy tử tế với chính mình."},{"start":350.96,"end":353.84,"text":"You don't need to be fast.","words":[["You",350.96],["don't",351.2],["need",351.44],["to",351.68],["be",351.92],["fast.",352.16]],"ipa":"/ju doʊnt nid tu bi fæst/","vi":"Bạn không cần phải nhanh chóng."},{"start":353.84,"end":357.12,"text":"You don't need to be perfect.","words":[["You",353.84],["don't",354.08],["need",354.56],["to",354.88],["be",355.12],["perfect.",355.44]],"ipa":"/ju doʊnt nid tu bi pərˈfɛkt/","vi":"Bạn không cần phải hoàn hảo."},{"start":357.12,"end":360.56,"text":"you just need to continue.","words":[["you",357.12],["just",357.44],["need",358],["to",358.32],["continue.",358.88]],"ipa":"/ju dʒʌst nid tu kənˈtɪnju/","vi":"bạn chỉ cần tiếp tục."},{"start":360.56,"end":366.72,"text":"So, how to stay motivated when you feel tired?","words":[["So,",360.56],["how",361.76],["to",362.08],["stay",362.32],["motivated",362.72],["when",363.52],["you",363.84],["feel",364.08],["tired?",364.8]],"ipa":"/soʊ haʊ tu steɪ ˈmoʊtəˌveɪtəd wɛn ju fil ˈtaɪərd/","vi":"Vậy làm thế nào để duy trì động lực khi bạn cảm thấy mệt mỏi?"},{"start":366.72,"end":368.16,"text":"Let's be honest.","words":[["Let's",366.72],["be",367.04],["honest.",367.2]],"ipa":"/lɛts bi ˈɑnəst/","vi":"Hãy thành thật đi."},{"start":368.16,"end":370.8,"text":"Some days you feel tired.","words":[["Some",368.16],["days",368.4],["you",368.8],["feel",369.12],["tired.",369.52]],"ipa":"/sʌm deɪz ju fil ˈtaɪərd/","vi":"Có những ngày bạn cảm thấy mệt mỏi."},{"start":370.8,"end":373.12,"text":"You feel busy.","words":[["You",370.8],["feel",371.12],["busy.",371.52]],"ipa":"/ju fil ˈbɪzi/","vi":"Bạn cảm thấy bận rộn."},{"start":373.12,"end":375.28,"text":"You feel stressed.","words":[["You",373.12],["feel",373.36],["stressed.",374.08]],"ipa":"/ju fil strɛst/","vi":"Bạn cảm thấy căng thẳng."},{"start":375.28,"end":379.28,"text":"You think, \\"I don't want to study today.\\"","words":[["You",375.28],["think,",375.52],["\\"I",376.16],["don't",376.56],["want",376.88],["to",377.12],["study",377.44],["today.\\"",377.92]],"ipa":"/ju θɪŋk aɪ doʊnt wɑnt tu ˈstʌdi təˈdeɪ/","vi":"Bạn nghĩ: “Hôm nay tôi không muốn học”."},{"start":379.28,"end":381.52,"text":"And that's okay.","words":[["And",379.28],["that's",379.52],["okay.",379.92]],"ipa":"/ənd ðæts ˌoʊˈkeɪ/","vi":"Và điều đó không sao cả."},{"start":381.52,"end":384.64,"text":"It's normal to feel tired.","words":[["It's",381.52],["normal",381.92],["to",382.4],["feel",382.72],["tired.",383.04]],"ipa":"/ɪts ˈnɔrməl tu fil ˈtaɪərd/","vi":"Cảm thấy mệt mỏi là điều bình thường."},{"start":384.64,"end":388.4,"text":"It's normal to take breaks.","words":[["It's",384.64],["normal",385.04],["to",385.68],["take",386.08],["breaks.",386.72]],"ipa":"/ɪts ˈnɔrməl tu teɪk breɪks/","vi":"Việc nghỉ giải lao là điều bình thường."},{"start":388.4,"end":392,"text":"Your brain needs rest, too.","words":[["Your",388.4],["brain",388.72],["needs",389.52],["rest,",389.92],["too.",390.64]],"ipa":"/jɔr breɪn nidz rɛst tu/","vi":"Bộ não của bạn cũng cần được nghỉ ngơi."},{"start":392,"end":397.52,"text":"But you can keep going even on hard days.","words":[["But",392],["you",392.16],["can",392.4],["keep",392.64],["going",393.04],["even",394.24],["on",394.88],["hard",395.2],["days.",395.6]],"ipa":"/bʌt ju kæn kip ˈɡoʊɪŋ ˈivɪn ɑn hɑrd deɪz/","vi":"Nhưng bạn có thể tiếp tục bước đi ngay cả trong những ngày khó khăn."},{"start":397.52,"end":400.4,"text":"Here are a few ideas.","words":[["Here",397.52],["are",397.84],["a",398.08],["few",398.32],["ideas.",398.8]],"ipa":"/hir ɑr ə fju aɪˈdiəz/","vi":"Dưới đây là một vài ý tưởng."},{"start":400.4,"end":405.6,"text":"Tip number one, do just a little.","words":[["Tip",400.4],["number",400.96],["one,",401.36],["do",402.32],["just",403.12],["a",403.52],["little.",403.76]],"ipa":"/tɪp ˈnʌmbər wʌn du dʒʌst ə ˈlɪtəl/","vi":"Mẹo số một, chỉ làm một chút thôi."},{"start":405.6,"end":409.36,"text":"You don't need to study for one hour.","words":[["You",405.6],["don't",405.84],["need",406],["to",406.24],["study",406.48],["for",406.8],["one",407.2],["hour.",407.6]],"ipa":"/ju doʊnt nid tu ˈstʌdi fɔr wʌn ˈaʊər/","vi":"Bạn không cần phải học trong một giờ."},{"start":409.36,"end":413.12,"text":"You don't need to do a big lesson.","words":[["You",409.36],["don't",409.6],["need",409.92],["to",410.16],["do",410.4],["a",410.72],["big",411.04],["lesson.",411.52]],"ipa":"/ju doʊnt nid tu du ə bɪɡ ˈlɛsən/","vi":"Bạn không cần phải làm một bài học lớn."},{"start":413.12,"end":417.28,"text":"Just do one small thing.","words":[["Just",413.12],["do",413.6],["one",414.4],["small",415.04],["thing.",415.52]],"ipa":"/dʒʌst du wʌn smɔl θɪŋ/","vi":"Chỉ cần làm một việc nhỏ."},{"start":417.28,"end":421.2,"text":"Listen to English for five minutes.","words":[["Listen",417.28],["to",417.68],["English",417.92],["for",418.56],["five",419.04],["minutes.",419.44]],"ipa":"/ˈlɪsən tu ˈɪŋɡlɪʃ fɔr faɪv ˈmɪnəts/","vi":"Nghe tiếng Anh trong năm phút."},{"start":421.2,"end":424.8,"text":"Read one short paragraph.","words":[["Read",421.2],["one",421.6],["short",422.08],["paragraph.",422.8]],"ipa":"/rɛd wʌn ʃɔrt ˈpærəˌɡræf/","vi":"Đọc một đoạn văn ngắn."},{"start":424.8,"end":428.48,"text":"Repeat one sentence in your head.","words":[["Repeat",424.8],["one",425.28],["sentence",425.68],["in",426.48],["your",426.8],["head.",427.04]],"ipa":"/rɪˈpit wʌn ˈsɛntəns ɪn jɔr hɛd/","vi":"Lặp lại một câu trong đầu."},{"start":428.48,"end":432.48,"text":"Even one minute is better than nothing.","words":[["Even",428.48],["one",428.96],["minute",429.28],["is",429.84],["better",430.24],["than",430.56],["nothing.",430.8]],"ipa":"/ˈivɪn wʌn ˈmɪnət ɪz ˈbɛtər ðæn ˈnʌθɪŋ/","vi":"Thậm chí một phút còn tốt hơn là không có gì."},{"start":432.48,"end":436.88,"text":"Learning English is not about doing a lot.","words":[["Learning",432.48],["English",432.96],["is",433.44],["not",433.84],["about",434.24],["doing",434.88],["a",435.28],["lot.",435.6]],"ipa":"/ˈlɝnɪŋ ˈɪŋɡlɪʃ ɪz nɑt əˈbaʊt ˈduɪŋ ə lɑt/","vi":"Học tiếng Anh không phải là làm nhiều."},{"start":436.88,"end":442.48,"text":"It's about doing a little again and again.","words":[["It's",436.88],["about",437.2],["doing",437.76],["a",438.08],["little",438.32],["again",439.12],["and",439.44],["again.",439.76]],"ipa":"/ɪts əˈbaʊt ˈduɪŋ ə ˈlɪtəl əˈɡɛn ənd əˈɡɛn/","vi":"Đó là về việc làm đi làm lại một chút."},{"start":442.48,"end":446.48,"text":"Tip number two, remember your reason.","words":[["Tip",442.48],["number",443.04],["two,",443.36],["remember",444.32],["your",445.12],["reason.",445.52]],"ipa":"/tɪp ˈnʌmbər tu rɪˈmɛmbər jɔr ˈrizən/","vi":"Mẹo số hai, hãy nhớ lý do của bạn."},{"start":446.48,"end":448.48,"text":"Why are you learning English?","words":[["Why",446.48],["are",446.8],["you",447.04],["learning",447.28],["English?",447.68]],"ipa":"/waɪ ɑr ju ˈlɝnɪŋ ˈɪŋɡlɪʃ/","vi":"Tại sao bạn học tiếng Anh?"},{"start":448.48,"end":450.8,"text":"Is it for your job?","words":[["Is",448.48],["it",448.72],["for",448.96],["your",449.2],["job?",449.52]],"ipa":"/ɪz ɪt fɔr jɔr dʒɑb/","vi":"Có phải vì công việc của bạn?"},{"start":450.8,"end":453.2,"text":"Is it to study abroad?","words":[["Is",450.8],["it",451.04],["to",451.2],["study",451.52],["abroad?",451.84]],"ipa":"/ɪz ɪt tu ˈstʌdi əˈbrɔd/","vi":"Có phải là đi du học không?"},{"start":453.2,"end":457.44,"text":"Is it to speak with people from around the world?","words":[["Is",453.2],["it",453.36],["to",453.68],["speak",454.08],["with",454.56],["people",454.96],["from",455.44],["around",455.92],["the",456.32],["world?",456.64]],"ipa":"/ɪz ɪt tu spik wɪð ˈpipəl frʌm ərˈaʊnd ðə wɝld/","vi":"Có phải để nói chuyện với mọi người từ khắp nơi trên thế giới?"},{"start":457.44,"end":460,"text":"Is it just for fun?","words":[["Is",457.44],["it",457.6],["just",458.24],["for",458.56],["fun?",458.88]],"ipa":"/ɪz ɪt dʒʌst fɔr fʌn/","vi":"Có phải nó chỉ để cho vui?"},{"start":460,"end":467.2,"text":"On the hard days, remember your why, your reason.","words":[["On",460],["the",460.24],["hard",460.48],["days,",460.8],["remember",461.76],["your",462.4],["why,",463.12],["your",464.64],["reason.",465.36]],"ipa":"/ɑn ðə hɑrd deɪz rɪˈmɛmbər jɔr waɪ jɔr ˈrizən/","vi":"Vào những ngày khó khăn, hãy nhớ đến lý do, lý do của bạn."},{"start":467.2,"end":468.88,"text":"Write it down.","words":[["Write",467.2],["it",467.44],["down.",467.68]],"ipa":"/raɪt ɪt daʊn/","vi":"Viết nó ra."},{"start":468.88,"end":470.88,"text":"Say it out loud.","words":[["Say",468.88],["it",469.12],["out",469.44],["loud.",469.68]],"ipa":"/seɪ ɪt aʊt laʊd/","vi":"Hãy nói to lên."},{"start":470.88,"end":472.96,"text":"Keep it close.","words":[["Keep",470.88],["it",471.12],["close.",471.44]],"ipa":"/kip ɪt kloʊs/","vi":"Giữ nó gần."},{"start":472.96,"end":476.8,"text":"Your reason is your fuel.","words":[["Your",472.96],["reason",473.28],["is",474.32],["your",474.88],["fuel.",475.36]],"ipa":"/jɔr ˈrizən ɪz jɔr ˈfjuəl/","vi":"Lý do của bạn là nhiên liệu của bạn."},{"start":476.8,"end":481.28,"text":"It gives you energy when you feel tired.","words":[["It",476.8],["gives",477.04],["you",477.28],["energy",477.6],["when",478.64],["you",478.96],["feel",479.2],["tired.",479.76]],"ipa":"/ɪt ɡɪvz ju ˈɛnərdʒi wɛn ju fil ˈtaɪərd/","vi":"Nó mang lại cho bạn năng lượng khi bạn cảm thấy mệt mỏi."},{"start":481.28,"end":486.16,"text":"Tip number three, make it easy.","words":[["Tip",481.28],["number",481.84],["three,",482.24],["make",483.2],["it",483.44],["easy.",484.08]],"ipa":"/tɪp ˈnʌmbər θri meɪk ɪt ˈizi/","vi":"Mẹo số ba, làm cho nó dễ dàng."},{"start":486.16,"end":489.28,"text":"Don't wait for the perfect time.","words":[["Don't",486.16],["wait",486.48],["for",486.96],["the",487.28],["perfect",487.6],["time.",488.24]],"ipa":"/doʊnt weɪt fɔr ðə pərˈfɛkt taɪm/","vi":"Đừng chờ đợi thời điểm hoàn hảo."},{"start":489.28,"end":495.28,"text":"Don't wait for silence or energy or the right mood.","words":[["Don't",489.28],["wait",489.68],["for",490.72],["silence",491.12],["or",491.92],["energy",492.4],["or",493.12],["the",493.68],["right",494],["mood.",494.32]],"ipa":"/doʊnt weɪt fɔr ˈsaɪləns ɔr ˈɛnərdʒi ɔr ðə raɪt mud/","vi":"Đừng chờ đợi sự im lặng, năng lượng hoặc tâm trạng thích hợp."},{"start":495.28,"end":498.32,"text":"Make English easy to start.","words":[["Make",495.28],["English",495.84],["easy",496.48],["to",496.96],["start.",497.28]],"ipa":"/meɪk ˈɪŋɡlɪʃ ˈizi tu stɑrt/","vi":"Làm cho tiếng Anh dễ dàng để bắt đầu."},{"start":498.32,"end":501.6,"text":"Put your book on your desk.","words":[["Put",498.32],["your",498.64],["book",498.88],["on",499.44],["your",499.76],["desk.",500]],"ipa":"/pʊt jɔr bʊk ɑn jɔr dɛsk/","vi":"Đặt cuốn sách của bạn trên bàn của bạn."},{"start":501.6,"end":505.12,"text":"Save a video on your phone.","words":[["Save",501.6],["a",501.92],["video",502.24],["on",502.88],["your",503.2],["phone.",503.44]],"ipa":"/seɪv ə ˈvɪdioʊ ɑn jɔr foʊn/","vi":"Lưu video trên điện thoại của bạn."},{"start":505.12,"end":509.12,"text":"Set a timer for 10 minutes.","words":[["Set",505.12],["a",505.44],["timer",505.76],["for",506.72],["10",507.12],["minutes.",507.6]],"ipa":"/sɛt ə ˈtaɪmər fɔr ˈmɪnəts/","vi":"Đặt đồng hồ hẹn giờ trong 10 phút."},{"start":509.12,"end":512.72,"text":"The goal is not to be perfect.","words":[["The",509.12],["goal",509.36],["is",510.08],["not",510.4],["to",510.64],["be",510.96],["perfect.",511.2]],"ipa":"/ðə ɡoʊl ɪz nɑt tu bi pərˈfɛkt/","vi":"Mục tiêu không phải là trở nên hoàn hảo."},{"start":512.72,"end":515.84,"text":"The goal is to start.","words":[["The",512.72],["goal",513.04],["is",513.68],["to",514],["start.",514.4]],"ipa":"/ðə ɡoʊl ɪz tu stɑrt/","vi":"Mục tiêu là để bắt đầu."},{"start":515.84,"end":520.4,"text":"And once you start, the rest becomes easier.","words":[["And",515.84],["once",516.08],["you",516.4],["start,",516.64],["the",517.76],["rest",518],["becomes",518.48],["easier.",519.36]],"ipa":"/ənd wʌns ju stɑrt ðə rɛst bɪˈkʌmz ˈiziər/","vi":"Và một khi bạn bắt đầu, phần còn lại sẽ trở nên dễ dàng hơn."},{"start":520.4,"end":525.84,"text":"Tip number four, be kind to yourself.","words":[["Tip",520.4],["number",520.88],["four,",521.28],["be",522.48],["kind",522.8],["to",523.52],["yourself.",523.84]],"ipa":"/tɪp ˈnʌmbər fɔr bi kaɪnd tu jərˈsɛlf/","vi":"Mẹo số bốn, hãy tử tế với chính mình."},{"start":525.84,"end":528.56,"text":"Don't say I'm slow.","words":[["Don't",525.84],["say",526.16],["I'm",526.8],["slow.",527.2]],"ipa":"/doʊnt seɪ aɪm sloʊ/","vi":"Đừng nói tôi chậm chạp."},{"start":528.56,"end":532.24,"text":"Don't say I'm bad at English.","words":[["Don't",528.56],["say",528.88],["I'm",529.6],["bad",529.92],["at",530.24],["English.",530.56]],"ipa":"/doʊnt seɪ aɪm bæd æt ˈɪŋɡlɪʃ/","vi":"Đừng nói tôi kém tiếng Anh."},{"start":532.24,"end":536.32,"text":"Don't say I will never speak well.","words":[["Don't",532.24],["say",532.56],["I",533.28],["will",533.52],["never",533.84],["speak",534.48],["well.",534.88]],"ipa":"/doʊnt seɪ aɪ wɪl ˈnɛvər spik wɛl/","vi":"Đừng nói rằng tôi sẽ không bao giờ nói tốt."},{"start":536.32,"end":542.64,"text":"Instead, say this, I'm learning. I'm trying.","words":[["Instead,",536.32],["say",537.28],["this,",537.6],["I'm",538.96],["learning.",539.28],["I'm",540.8],["trying.",541.28]],"ipa":"/ˌɪnˈstɛd seɪ ðɪs aɪm ˈlɝnɪŋ aɪm ˈtraɪɪŋ/","vi":"Thay vào đó hãy nói điều này, tôi đang học. Tôi đang cố gắng."},{"start":542.64,"end":547.6,"text":"I'm doing something difficult and I'm doing my best.","words":[["I'm",542.64],["doing",543.04],["something",543.36],["difficult",544.08],["and",544.96],["I'm",545.28],["doing",545.6],["my",545.92],["best.",546.24]],"ipa":"/aɪm ˈduɪŋ ˈsʌmθɪŋ ˈdɪfəkəlt ənd aɪm ˈduɪŋ maɪ bɛst/","vi":"Tôi đang làm điều gì đó khó khăn và tôi đang cố gắng hết sức."},{"start":547.6,"end":549.28,"text":"You are human.","words":[["You",547.6],["are",547.92],["human.",548.08]],"ipa":"/ju ɑr ˈhjumən/","vi":"Bạn là con người."},{"start":549.28,"end":551.12,"text":"You are growing.","words":[["You",549.28],["are",549.52],["growing.",549.84]],"ipa":"/ju ɑr ˈɡroʊɪŋ/","vi":"Bạn đang phát triển."},{"start":551.12,"end":554.16,"text":"So be kind to yourself.","words":[["So",551.12],["be",551.76],["kind",552.08],["to",552.64],["yourself.",552.96]],"ipa":"/soʊ bi kaɪnd tu jərˈsɛlf/","vi":"Vì vậy hãy tử tế với chính mình."},{"start":554.16,"end":560.8,"text":"You deserve kindness from others and from yourself.","words":[["You",554.16],["deserve",554.48],["kindness",555.2],["from",556.64],["others",556.96],["and",558.16],["from",559.2],["yourself.",559.6]],"ipa":"/ju dɪˈzɝv ˈkaɪndnəs frʌm ˈʌðərz ənd frʌm jərˈsɛlf/","vi":"Bạn xứng đáng nhận được lòng tốt từ người khác và từ chính mình."},{"start":560.8,"end":566.32,"text":"Tip number five, celebrate small wins.","words":[["Tip",560.8],["number",561.28],["five,",561.68],["celebrate",563.28],["small",564.56],["wins.",565.36]],"ipa":"/tɪp ˈnʌmbər faɪv ˈsɛləˌbreɪt smɔl wɪnz/","vi":"Mẹo số năm, hãy ăn mừng những chiến thắng nhỏ."},{"start":566.32,"end":569.44,"text":"Did you listen to English today?","words":[["Did",566.32],["you",566.56],["listen",566.72],["to",567.04],["English",567.28],["today?",567.84]],"ipa":"/dɪd ju ˈlɪsən tu ˈɪŋɡlɪʃ təˈdeɪ/","vi":"Hôm nay bạn có nghe tiếng Anh không?"},{"start":569.44,"end":571.52,"text":"That's a win.","words":[["That's",569.44],["a",569.76],["win.",570]],"ipa":"/ðæts ə wɪn/","vi":"Đó là một chiến thắng."},{"start":571.52,"end":574.4,"text":"Did you learn one new word?","words":[["Did",571.52],["you",571.76],["learn",572],["one",572.48],["new",572.8],["word?",573.12]],"ipa":"/dɪd ju lɝn wʌn nu wɝd/","vi":"Bạn đã học được một từ mới?"},{"start":574.4,"end":576,"text":"That's a win.","words":[["That's",574.4],["a",574.72],["win.",574.96]],"ipa":"/ðæts ə wɪn/","vi":"Đó là một chiến thắng."},{"start":576,"end":579.2,"text":"Did you try even a little?","words":[["Did",576],["you",576.24],["try",576.4],["even",577.36],["a",577.68],["little?",577.92]],"ipa":"/dɪd ju traɪ ˈivɪn ə ˈlɪtəl/","vi":"Bạn đã cố gắng dù chỉ một chút?"},{"start":579.2,"end":581.28,"text":"That's a win, too.","words":[["That's",579.2],["a",579.52],["win,",579.76],["too.",580.24]],"ipa":"/ðæts ə wɪn tu/","vi":"Đó cũng là một chiến thắng."},{"start":581.28,"end":584.16,"text":"You don't need big results.","words":[["You",581.28],["don't",581.52],["need",581.76],["big",582.24],["results.",582.64]],"ipa":"/ju doʊnt nid bɪɡ rɪˈzʌlts/","vi":"Bạn không cần kết quả lớn."},{"start":584.16,"end":591.04,"text":"You just need to notice the small victories, the small wins.","words":[["You",584.16],["just",584.48],["need",584.72],["to",584.96],["notice",585.2],["the",585.92],["small",586.32],["victories,",587.2],["the",588.56],["small",588.96],["wins.",589.68]],"ipa":"/ju dʒʌst nid tu ˈnoʊtəs ðə smɔl ˈvɪktəriz ðə smɔl wɪnz/","vi":"Bạn chỉ cần để ý những thắng lợi nhỏ, những thắng lợi nhỏ."},{"start":591.04,"end":598.88,"text":"Smile at them, feel good about them because they matter. Okay.","words":[["Smile",591.04],["at",591.36],["them,",591.6],["feel",592.72],["good",593.28],["about",593.76],["them",594.16],["because",595.12],["they",596.16],["matter.",596.48],["Okay.",598]],"ipa":"/smaɪl æt ðɛm fil ɡʊd əˈbaʊt ðɛm bɪˈkɔz ðeɪ ˈmætər ˌoʊˈkeɪ/","vi":"Hãy mỉm cười với họ, cảm thấy hài lòng về họ vì họ quan trọng. Được rồi."},{"start":598.88,"end":607.04,"text":"In this part of the episode, I will speak using slightly longer sentences than before.","words":[["In",598.88],["this",599.12],["part",599.28],["of",599.52],["the",599.76],["episode,",600],["I",601.2],["will",601.52],["speak",601.76],["using",602.16],["slightly",603.04],["longer",603.76],["sentences",604.4],["than",605.12],["before.",605.52]],"ipa":"/ɪn ðɪs pɑrt ʌv ðə ˈɛpəˌsoʊd aɪ wɪl spik ˈjuzɪŋ ˈslaɪtli ˈlɔŋɡər ˈsɛntənsəz ðæn bɪˈfɔr/","vi":"Trong phần này của tập phim, tôi sẽ nói bằng những câu dài hơn trước một chút."},{"start":607.04,"end":613.36,"text":"Still slow, still simple, but just a little longer.","words":[["Still",607.04],["slow,",607.44],["still",608.48],["simple,",608.88],["but",610.16],["just",610.48],["a",610.8],["little",611.12],["longer.",611.68]],"ipa":"/stɪl sloʊ stɪl ˈsɪmpəl bʌt dʒʌst ə ˈlɪtəl ˈlɔŋɡər/","vi":"Vẫn chậm, vẫn đơn giản, nhưng chỉ lâu hơn một chút thôi."},{"start":613.36,"end":619.04,"text":"This will help your listening improve step by step.","words":[["This",613.36],["will",613.76],["help",614.08],["your",614.32],["listening",614.56],["improve",615.28],["step",616.88],["by",617.44],["step.",618.08]],"ipa":"/ðɪs wɪl hɛlp jɔr ˈlɪsənɪŋ ˌɪmˈpruv stɛp baɪ stɛp/","vi":"Điều này sẽ giúp khả năng nghe của bạn được cải thiện từng bước."},{"start":619.04,"end":625.12,"text":"So don't worry if you don't understand every word. That's okay.","words":[["So",619.04],["don't",619.44],["worry",619.84],["if",620.48],["you",620.88],["don't",621.12],["understand",621.44],["every",622.24],["word.",622.72],["That's",623.6],["okay.",624]],"ipa":"/soʊ doʊnt ˈwɝi ɪf ju doʊnt ˌʌndərˈstænd ˈɛvəri wɝd ðæts ˌoʊˈkeɪ/","vi":"Vì vậy, đừng lo lắng nếu bạn không hiểu từng từ. Không sao đâu."},{"start":625.12,"end":629.68,"text":"Just listen, relax, and try to follow the meaning.","words":[["Just",625.12],["listen,",625.44],["relax,",626.4],["and",627.28],["try",627.6],["to",627.84],["follow",628.08],["the",628.32],["meaning.",628.56]],"ipa":"/dʒʌst ˈlɪsən rɪˈlæks ənd traɪ tu ˈfɑloʊ ðə ˈminɪŋ/","vi":"Chỉ cần lắng nghe, thư giãn và cố gắng hiểu ý nghĩa."},{"start":629.68,"end":632.4,"text":"Learning English takes time.","words":[["Learning",629.68],["English",630.16],["takes",630.8],["time.",631.36]],"ipa":"/ˈlɝnɪŋ ˈɪŋɡlɪʃ teɪks taɪm/","vi":"Học tiếng Anh cần có thời gian."},{"start":632.4,"end":636.72,"text":"But sometimes you don't feel your progress.","words":[["But",632.4],["sometimes",632.56],["you",633.76],["don't",634],["feel",634.56],["your",635.12],["progress.",635.52]],"ipa":"/bʌt səmˈtaɪmz ju doʊnt fil jɔr ˈprɑˌɡrɛs/","vi":"Nhưng đôi khi bạn không cảm nhận được sự tiến bộ của mình."},{"start":636.72,"end":645.92,"text":"You study, you listen, you practice, and still you ask, \\"Am I improving?","words":[["You",636.72],["study,",637.04],["you",638.08],["listen,",638.32],["you",639.6],["practice,",639.92],["and",641.36],["still",641.68],["you",642.08],["ask,",642.4],["\\"Am",643.68],["I",644],["improving?",644.24]],"ipa":"/ju ˈstʌdi ju ˈlɪsən ju ˈpræktəs ənd stɪl ju æsk æm aɪ ˌɪmˈpruvɪŋ/","vi":"Bạn học, bạn nghe, bạn thực hành, nhưng bạn vẫn hỏi, \\"Tôi có tiến bộ không?"},{"start":645.92,"end":648.24,"text":"Is this working?","words":[["Is",645.92],["this",646.16],["working?",646.72]],"ipa":"/ɪz ðɪs ˈwɝkɪŋ/","vi":"Cái này có hoạt động không?"},{"start":648.24,"end":652.72,"text":"Why is my English still not good enough?\\"","words":[["Why",648.24],["is",648.48],["my",648.72],["English",648.96],["still",649.76],["not",650.16],["good",650.64],["enough?\\"",650.88]],"ipa":"/waɪ ɪz maɪ ˈɪŋɡlɪʃ stɪl nɑt ɡʊd ɪˈnʌf/","vi":"Tại sao tiếng Anh của tôi vẫn chưa đủ tốt?”"},{"start":652.72,"end":654.72,"text":"But here's the truth.","words":[["But",652.72],["here's",652.96],["the",653.28],["truth.",653.52]],"ipa":"/bʌt hɪrz ðə truθ/","vi":"Nhưng đây là sự thật."},{"start":654.72,"end":657.44,"text":"You are improving.","words":[["You",654.72],["are",655.12],["improving.",655.76]],"ipa":"/ju ɑr ˌɪmˈpruvɪŋ/","vi":"Bạn đang cải thiện."},{"start":657.44,"end":665.84,"text":"You are better today than you were yesterday, even if you don't see it yet.","words":[["You",657.44],["are",657.84],["better",658.56],["today",658.96],["than",659.84],["you",660.16],["were",660.4],["yesterday,",660.96],["even",662.56],["if",662.8],["you",663.12],["don't",663.44],["see",664.08],["it",664.24],["yet.",664.56]],"ipa":"/ju ɑr ˈbɛtər təˈdeɪ ðæn ju wɝ ˈjɛstərˌdeɪ ˈivɪn ɪf ju doʊnt si ɪt jɛt/","vi":"Hôm nay bạn tốt hơn ngày hôm qua, ngay cả khi bạn chưa nhìn thấy điều đó."},{"start":665.84,"end":670.56,"text":"So, how can you see your progress?","words":[["So,",665.84],["how",666.72],["can",666.96],["you",667.2],["see",667.44],["your",668.16],["progress?",668.64]],"ipa":"/soʊ haʊ kæn ju si jɔr ˈprɑˌɡrɛs/","vi":"Vì vậy, làm thế nào bạn có thể thấy sự tiến bộ của bạn?"},{"start":670.56,"end":675.44,"text":"How can you feel that learning is working?","words":[["How",670.56],["can",670.8],["you",671.04],["feel",671.28],["that",671.6],["learning",671.92],["is",672.88],["working?",673.28]],"ipa":"/haʊ kæn ju fil ðæt ˈlɝnɪŋ ɪz ˈwɝkɪŋ/","vi":"Làm thế nào bạn có thể cảm thấy việc học tập đang có hiệu quả?"},{"start":675.44,"end":679.28,"text":"Let's talk about a few simple ways.","words":[["Let's",675.44],["talk",675.76],["about",676],["a",676.64],["few",677.04],["simple",677.44],["ways.",678.16]],"ipa":"/lɛts tɔk əˈbaʊt ə fju ˈsɪmpəl weɪz/","vi":"Hãy nói về một vài cách đơn giản."},{"start":679.28,"end":686,"text":"Tip number one, write things down often.","words":[["Tip",679.28],["number",679.84],["one,",680.24],["write",682.16],["things",682.8],["down",683.36],["often.",684.4]],"ipa":"/tɪp ˈnʌmbər wʌn raɪt θɪŋz daʊn ˈɔfən/","vi":"Mẹo số một, hãy viết ra mọi thứ thường xuyên."},{"start":686,"end":695.36,"text":"If you can keep a little English notebook, in this notebook, you can write new words you learn,","words":[["If",686],["you",686.24],["can",686.4],["keep",687.44],["a",687.76],["little",688.08],["English",688.4],["notebook,",689.04],["in",690.24],["this",690.48],["notebook,",690.72],["you",691.92],["can",692.16],["write",692.4],["new",693.04],["words",693.36],["you",693.76],["learn,",694.08]],"ipa":"/ɪf ju kæn kip ə ˈlɪtəl ˈɪŋɡlɪʃ ˈnoʊtˌbʊk ɪn ðɪs ˈnoʊtˌbʊk ju kæn raɪt nu wɝdz ju lɝn/","vi":"Nếu bạn có thể giữ một cuốn sổ tiếng Anh nhỏ, trong cuốn sổ này, bạn có thể viết những từ mới bạn học được,"},{"start":695.36,"end":701.68,"text":"sentences you like, and things you did in English today.","words":[["sentences",695.36],["you",696.16],["like,",696.48],["and",697.68],["things",698.48],["you",698.88],["did",699.2],["in",699.52],["English",699.84],["today.",700.48]],"ipa":"/ˈsɛntənsəz ju laɪk ənd θɪŋz ju dɪd ɪn ˈɪŋɡlɪʃ təˈdeɪ/","vi":"những câu bạn thích và những việc bạn đã làm bằng tiếng Anh ngày hôm nay."},{"start":701.68,"end":704.8,"text":"You don't have to write a lot.","words":[["You",701.68],["don't",701.92],["have",702.16],["to",702.32],["write",702.56],["a",703.12],["lot.",703.44]],"ipa":"/ju doʊnt hæv tu raɪt ə lɑt/","vi":"Bạn không cần phải viết nhiều."},{"start":704.8,"end":709.44,"text":"Even one sentence per day is enough.","words":[["Even",704.8],["one",705.44],["sentence",705.76],["per",706.24],["day",706.64],["is",707.28],["enough.",707.6]],"ipa":"/ˈivɪn wʌn ˈsɛntəns pɝ deɪ ɪz ɪˈnʌf/","vi":"Thậm chí một câu mỗi ngày là đủ."},{"start":709.44,"end":715.76,"text":"For example, today I listened to a podcast.","words":[["For",709.44],["example,",709.6],["today",711.52],["I",712.4],["listened",712.8],["to",713.28],["a",713.52],["podcast.",713.76]],"ipa":"/fɔr ɪɡˈzæmpəl təˈdeɪ aɪ ˈlɪsənd tu ə ˈpɔdˌkæst/","vi":"Ví dụ, hôm nay tôi nghe một podcast."},{"start":715.76,"end":720,"text":"I learned the word progress.","words":[["I",715.76],["learned",716.08],["the",716.56],["word",716.88],["progress.",717.76]],"ipa":"/aɪ lɝnd ðə wɝd ˈprɑˌɡrɛs/","vi":"Tôi đã học được từ tiến bộ."},{"start":720,"end":724.72,"text":"I watched a video and understood it.","words":[["I",720],["watched",720.32],["a",720.72],["video",721.04],["and",721.84],["understood",722.48],["it.",723.12]],"ipa":"/aɪ wɑtʃt ə ˈvɪdioʊ ənd ˌʌndərˈstʊd ɪt/","vi":"Tôi đã xem một video và hiểu nó."},{"start":724.72,"end":734.08,"text":"Later, maybe in one week or one month, you can read it again and you will be surprised.","words":[["Later,",724.72],["maybe",725.6],["in",726.08],["one",726.4],["week",726.64],["or",727.04],["one",727.6],["month,",727.92],["you",729.04],["can",729.28],["read",729.6],["it",729.92],["again",730.16],["and",731.44],["you",731.76],["will",731.92],["be",732.16],["surprised.",732.32]],"ipa":"/ˈleɪtər ˈmeɪbi ɪn wʌn wik ɔr wʌn mʌnθ ju kæn rɛd ɪt əˈɡɛn ənd ju wɪl bi sərˈpraɪzd/","vi":"Sau này, có thể một tuần hoặc một tháng, bạn có thể đọc lại nó và bạn sẽ ngạc nhiên."},{"start":734.08,"end":738.88,"text":"You will say, \\"Oh, I remember when I learned this.","words":[["You",734.08],["will",734.32],["say,",734.56],["\\"Oh,",735.04],["I",736],["remember",736.4],["when",736.8],["I",737.12],["learned",737.36],["this.",737.68]],"ipa":"/ju wɪl seɪ oʊ aɪ rɪˈmɛmbər wɛn aɪ lɝnd ðɪs/","vi":"Bạn sẽ nói, \\"Ồ, tôi nhớ khi tôi học được điều này."},{"start":738.88,"end":744.24,"text":"This was so hard before, but now it feels easy.\\"","words":[["This",738.88],["was",739.2],["so",739.44],["hard",739.76],["before,",740.08],["but",740.96],["now",741.28],["it",741.84],["feels",742.16],["easy.\\"",742.72]],"ipa":"/ðɪs wɑz soʊ hɑrd bɪˈfɔr bʌt naʊ ɪt filz ˈizi/","vi":"Trước đây việc này thật khó khăn nhưng bây giờ tôi cảm thấy dễ dàng”."},{"start":744.24,"end":748.4,"text":"That, my friend, is real progress.","words":[["That,",744.24],["my",744.96],["friend,",745.28],["is",745.92],["real",746.32],["progress.",746.88]],"ipa":"/ðæt maɪ frɛnd ɪz ril ˈprɑˌɡrɛs/","vi":"Bạn của tôi, đó là sự tiến bộ thực sự."},{"start":748.4,"end":752.72,"text":"Tip number two, record your voice.","words":[["Tip",748.4],["number",748.88],["two,",749.28],["record",750.64],["your",751.36],["voice.",751.76]],"ipa":"/tɪp ˈnʌmbər tu rəˈkɔrd jɔr vɔɪs/","vi":"Mẹo số hai, ghi lại giọng nói của bạn."},{"start":752.72,"end":757.28,"text":"You don't need a fancy microphone like mine.","words":[["You",752.72],["don't",752.96],["need",753.2],["a",753.44],["fancy",753.76],["microphone",754.48],["like",755.44],["mine.",755.76]],"ipa":"/ju doʊnt nid ə ˈfænsi ˈmaɪkrəˌfoʊn laɪk maɪn/","vi":"Bạn không cần một chiếc micro cầu kỳ như của tôi."},{"start":757.28,"end":760.16,"text":"Just use your phone.","words":[["Just",757.28],["use",757.76],["your",758.08],["phone.",758.48]],"ipa":"/dʒʌst jus jɔr foʊn/","vi":"Chỉ cần sử dụng điện thoại của bạn."},{"start":760.16,"end":763.92,"text":"Say one or two sentences in English.","words":[["Say",760.16],["one",760.56],["or",761.04],["two",761.36],["sentences",761.6],["in",762.24],["English.",762.56]],"ipa":"/seɪ wʌn ɔr tu ˈsɛntənsəz ɪn ˈɪŋɡlɪʃ/","vi":"Nói một hoặc hai câu bằng tiếng Anh."},{"start":763.92,"end":767.76,"text":"For example, hello, my name's Sarah.","words":[["For",763.92],["example,",764],["hello,",765.12],["my",766.24],["name's",766.48],["Sarah.",766.8]],"ipa":"/fɔr ɪɡˈzæmpəl həˈloʊ maɪ neɪmz ˈsɛrə/","vi":"Ví dụ: xin chào, tên tôi là Sarah."},{"start":767.76,"end":769.6,"text":"I live in Turkey.","words":[["I",767.76],["live",768.08],["in",768.24],["Turkey.",768.48]],"ipa":"/aɪ laɪv ɪn ˈtɝki/","vi":"Tôi sống ở Thổ Nhĩ Kỳ."},{"start":769.6,"end":773.92,"text":"I'm learning English because I want to study abroad.","words":[["I'm",769.6],["learning",769.92],["English",770.24],["because",770.96],["I",771.44],["want",771.76],["to",771.92],["study",772.16],["abroad.",772.64]],"ipa":"/aɪm ˈlɝnɪŋ ˈɪŋɡlɪʃ bɪˈkɔz aɪ wɑnt tu ˈstʌdi əˈbrɔd/","vi":"Tôi học tiếng Anh vì tôi muốn đi du học."},{"start":773.92,"end":777.92,"text":"Then next week, do it again.","words":[["Then",773.92],["next",774.88],["week,",775.2],["do",776.24],["it",776.48],["again.",776.64]],"ipa":"/ðɛn nɛkst wik du ɪt əˈɡɛn/","vi":"Rồi tuần sau hãy làm lại."},{"start":777.92,"end":780.32,"text":"Say the same thing.","words":[["Say",777.92],["the",778.24],["same",778.56],["thing.",778.88]],"ipa":"/seɪ ðə seɪm θɪŋ/","vi":"Nói điều tương tự."},{"start":780.32,"end":784.56,"text":"Then listen and compare the two.","words":[["Then",780.32],["listen",780.64],["and",781.76],["compare",782.16],["the",782.8],["two.",783.12]],"ipa":"/ðɛn ˈlɪsən ənd kəmˈpɛr ðə tu/","vi":"Sau đó hãy nghe và so sánh cả hai."},{"start":784.56,"end":789.52,"text":"You will notice your pronunciation is a little better.","words":[["You",784.56],["will",784.8],["notice",785.04],["your",785.68],["pronunciation",786],["is",787.04],["a",787.6],["little",787.92],["better.",788.32]],"ipa":"/ju wɪl ˈnoʊtəs jɔr proʊˌnʌnsiˈeɪʃən ɪz ə ˈlɪtəl ˈbɛtər/","vi":"Bạn sẽ nhận thấy cách phát âm của mình tốt hơn một chút."},{"start":789.52,"end":793.44,"text":"Your voice is a little more confident.","words":[["Your",789.52],["voice",789.76],["is",790.72],["a",791.12],["little",791.44],["more",791.76],["confident.",792.24]],"ipa":"/jɔr vɔɪs ɪz ə ˈlɪtəl mɔr ˈkɑnfədənt/","vi":"Giọng nói của bạn tự tin hơn một chút."},{"start":793.44,"end":797.6,"text":"This is how you see your progress.","words":[["This",793.44],["is",793.68],["how",793.92],["you",794.48],["see",794.96],["your",795.84],["progress.",796.24]],"ipa":"/ðɪs ɪz haʊ ju si jɔr ˈprɑˌɡrɛs/","vi":"Đây là cách bạn nhìn thấy sự tiến bộ của mình."},{"start":797.6,"end":799.52,"text":"It becomes real.","words":[["It",797.6],["becomes",797.84],["real.",798.4]],"ipa":"/ɪt bɪˈkʌmz ril/","vi":"Nó trở thành hiện thực."},{"start":799.52,"end":802.8,"text":"It becomes something you can hear.","words":[["It",799.52],["becomes",799.76],["something",800.64],["you",801.52],["can",801.84],["hear.",802.08]],"ipa":"/ɪt bɪˈkʌmz ˈsʌmθɪŋ ju kæn hir/","vi":"Nó trở thành thứ bạn có thể nghe thấy."},{"start":802.8,"end":808.48,"text":"Tip number three, notice small things you understand.","words":[["Tip",802.8],["number",803.28],["three,",803.68],["notice",805.04],["small",805.92],["things",806.4],["you",806.96],["understand.",807.28]],"ipa":"/tɪp ˈnʌmbər θri ˈnoʊtəs smɔl θɪŋz ju ˌʌndərˈstænd/","vi":"Mẹo số ba, hãy để ý những điều nhỏ nhặt mà bạn hiểu được."},{"start":808.48,"end":812.4,"text":"Progress is not always big, my friends.","words":[["Progress",808.48],["is",809.12],["not",809.44],["always",809.76],["big,",810.32],["my",810.8],["friends.",811.04]],"ipa":"/ˈprɑˌɡrɛs ɪz nɑt ˈɔlˌweɪz bɪɡ maɪ frɛndz/","vi":"Sự tiến bộ không phải lúc nào cũng lớn, các bạn ạ."},{"start":812.4,"end":817.68,"text":"It's not always a test score or a certificate.","words":[["It's",812.4],["not",812.64],["always",812.88],["a",813.36],["test",813.68],["score",814.24],["or",815.12],["a",815.84],["certificate.",816.08]],"ipa":"/ɪts nɑt ˈɔlˌweɪz ə tɛst skɔr ɔr ə sərˈtɪfɪkət/","vi":"Nó không phải lúc nào cũng là điểm kiểm tra hoặc chứng chỉ."},{"start":817.68,"end":820.16,"text":"Sometimes it's quiet.","words":[["Sometimes",817.68],["it's",818.32],["quiet.",818.72]],"ipa":"/səmˈtaɪmz ɪts ˈkwaɪət/","vi":"Đôi khi nó yên tĩnh."},{"start":820.16,"end":825.12,"text":"It's the moment you understand a sentence without thinking.","words":[["It's",820.16],["the",820.4],["moment",820.72],["you",821.04],["understand",821.36],["a",821.92],["sentence",822.24],["without",822.96],["thinking.",823.76]],"ipa":"/ɪts ðə ˈmoʊmənt ju ˌʌndərˈstænd ə ˈsɛntəns wɪˈθaʊt ˈθɪŋkɪŋ/","vi":"Đó là khoảnh khắc bạn hiểu một câu mà không cần suy nghĩ."},{"start":825.12,"end":831.36,"text":"It's the first time you watch a video without subtitles.","words":[["It's",825.12],["the",825.44],["first",825.76],["time",826.08],["you",826.72],["watch",827.04],["a",827.28],["video",827.6],["without",828.32],["subtitles.",829.12]],"ipa":"/ɪts ðə fɝst taɪm ju wɑtʃ ə ˈvɪdioʊ wɪˈθaʊt ˈsʌbˌtaɪtəlz/","vi":"Đây là lần đầu tiên bạn xem một video không có phụ đề."},{"start":831.36,"end":837.2,"text":"It's when you speak and don't translate in your head.","words":[["It's",831.36],["when",831.68],["you",831.92],["speak",832.24],["and",833.12],["don't",833.44],["translate",833.92],["in",834.8],["your",835.12],["head.",835.28]],"ipa":"/ɪts wɛn ju spik ənd doʊnt trænzˈleɪt ɪn jɔr hɛd/","vi":"Đó là khi bạn nói và không dịch trong đầu."},{"start":837.2,"end":846.4,"text":"These are small quiet signs, but they are big victories, big wins.","words":[["These",837.2],["are",837.6],["small",838],["quiet",839.12],["signs,",840.08],["but",841.36],["they",841.68],["are",842],["big",842.48],["victories,",842.96],["big",844.48],["wins.",845.2]],"ipa":"/ðiz ɑr smɔl ˈkwaɪət saɪnz bʌt ðeɪ ɑr bɪɡ ˈvɪktəriz bɪɡ wɪnz/","vi":"Đó là những dấu hiệu nhỏ thầm lặng nhưng lại là những thắng lợi lớn, thắng lợi lớn."},{"start":846.4,"end":851.92,"text":"Tip number four, look back, not just forward.","words":[["Tip",846.4],["number",846.96],["four,",847.28],["look",848.24],["back,",848.56],["not",849.44],["just",849.76],["forward.",850.48]],"ipa":"/tɪp ˈnʌmbər fɔr lʊk bæk nɑt dʒʌst ˈfɔrwərd/","vi":"Mẹo số bốn, hãy nhìn lại, không chỉ nhìn về phía trước."},{"start":851.92,"end":856.48,"text":"Sometimes we only look at what we don't know.","words":[["Sometimes",851.92],["we",852.88],["only",853.2],["look",853.6],["at",853.76],["what",854.24],["we",854.48],["don't",854.88],["know.",855.28]],"ipa":"/səmˈtaɪmz wi ˈoʊnli lʊk æt wʌt wi doʊnt noʊ/","vi":"Đôi khi chúng ta chỉ nhìn vào những gì chúng ta không biết."},{"start":856.48,"end":860.88,"text":"We say, \\"I don't understand native speakers.","words":[["We",856.48],["say,",856.8],["\\"I",857.28],["don't",857.68],["understand",857.92],["native",858.88],["speakers.",859.44]],"ipa":"/wi seɪ aɪ doʊnt ˌʌndərˈstænd ˈneɪtɪv ˈspikərz/","vi":"Chúng ta nói: \\"Tôi không hiểu người bản xứ."},{"start":860.88,"end":863.68,"text":"I can't speak fast.","words":[["I",860.88],["can't",861.2],["speak",861.52],["fast.",862.08]],"ipa":"/aɪ kænt spik fæst/","vi":"Tôi không thể nói nhanh."},{"start":863.68,"end":867.44,"text":"I still make mistakes.\\"","words":[["I",863.68],["still",864],["make",864.48],["mistakes.\\"",864.96]],"ipa":"/aɪ stɪl meɪk mɪˈsteɪks/","vi":"Tôi vẫn mắc sai lầm”."},{"start":867.44,"end":872.64,"text":"But try something different. Look back.","words":[["But",867.44],["try",867.68],["something",867.92],["different.",868.48],["Look",870.32],["back.",871.12]],"ipa":"/bʌt traɪ ˈsʌmθɪŋ ˈdɪfərənt lʊk bæk/","vi":"Nhưng hãy thử một cái gì đó khác biệt. Nhìn lại."},{"start":872.64,"end":877.68,"text":"Look at what you could not do one month ago.","words":[["Look",872.64],["at",872.88],["what",873.28],["you",873.52],["could",873.76],["not",874.16],["do",874.64],["one",875.52],["month",875.76],["ago.",876]],"ipa":"/lʊk æt wʌt ju kʊd nɑt du wʌn mʌnθ əˈɡoʊ/","vi":"Hãy nhìn lại những gì bạn không thể làm được một tháng trước."},{"start":877.68,"end":881.6,"text":"Now look at what you can do today.","words":[["Now",877.68],["look",878.64],["at",878.8],["what",879.04],["you",879.36],["can",879.68],["do",880.08],["today.",880.64]],"ipa":"/naʊ lʊk æt wʌt ju kæn du təˈdeɪ/","vi":"Bây giờ hãy xem bạn có thể làm gì hôm nay."},{"start":881.6,"end":886.88,"text":"Could you understand this podcast two months ago?","words":[["Could",881.6],["you",881.84],["understand",882.16],["this",882.72],["podcast",883.04],["two",884.64],["months",884.88],["ago?",885.12]],"ipa":"/kʊd ju ˌʌndərˈstænd ðɪs ˈpɔdˌkæst tu mʌnθs əˈɡoʊ/","vi":"Bạn có thể hiểu podcast này hai tháng trước không?"},{"start":886.88,"end":890.88,"text":"Could you say two full sentences?","words":[["Could",886.88],["you",887.12],["say",887.28],["two",887.76],["full",888.08],["sentences?",888.48]],"ipa":"/kʊd ju seɪ tu fʊl ˈsɛntənsəz/","vi":"Bạn có thể nói hai câu đầy đủ được không?"},{"start":890.88,"end":894.72,"text":"Could you write three lines in English?","words":[["Could",890.88],["you",891.12],["write",891.36],["three",892],["lines",892.4],["in",892.96],["English?",893.28]],"ipa":"/kʊd ju raɪt θri laɪnz ɪn ˈɪŋɡlɪʃ/","vi":"Bạn có thể viết ba dòng bằng tiếng Anh được không?"},{"start":894.72,"end":900,"text":"Looking back helps you understand you are growing.","words":[["Looking",894.72],["back",895.2],["helps",895.76],["you",896.08],["understand",896.32],["you",897.76],["are",898.16],["growing.",898.72]],"ipa":"/ˈlʊkɪŋ bæk hɛlps ju ˌʌndərˈstænd ju ɑr ˈɡroʊɪŋ/","vi":"Nhìn lại giúp bạn hiểu rằng bạn đang phát triển."},{"start":900,"end":902.48,"text":"You are not stuck.","words":[["You",900],["are",900.24],["not",900.4],["stuck.",901.2]],"ipa":"/ju ɑr nɑt stʌk/","vi":"Bạn không bị mắc kẹt."},{"start":902.48,"end":904.64,"text":"you are moving.","words":[["you",902.48],["are",902.8],["moving.",903.36]],"ipa":"/ju ɑr ˈmuvɪŋ/","vi":"bạn đang di chuyển."},{"start":904.64,"end":913.76,"text":"Sometimes progress is slow but slow progress is still progress. Okay.","words":[["Sometimes",904.64],["progress",905.84],["is",906.56],["slow",907.28],["but",908.64],["slow",909.04],["progress",909.44],["is",910.32],["still",910.72],["progress.",911.68],["Okay.",912.88]],"ipa":"/səmˈtaɪmz ˈprɑˌɡrɛs ɪz sloʊ bʌt sloʊ ˈprɑˌɡrɛs ɪz stɪl ˈprɑˌɡrɛs ˌoʊˈkeɪ/","vi":"Đôi khi tiến bộ chậm nhưng tiến bộ chậm vẫn là tiến bộ. Được rồi."},{"start":913.76,"end":920,"text":"In this part of the podcast, I will talk about something very important.","words":[["In",913.76],["this",914],["part",914.24],["of",914.48],["the",914.64],["podcast,",914.88],["I",916.32],["will",916.56],["talk",916.8],["about",917.12],["something",917.44],["very",918.32],["important.",918.96]],"ipa":"/ɪn ðɪs pɑrt ʌv ðə ˈpɔdˌkæst aɪ wɪl tɔk əˈbaʊt ˈsʌmθɪŋ ˈvɛri ˌɪmˈpɔrtənt/","vi":"Trong phần podcast này, tôi sẽ nói về một điều rất quan trọng."},{"start":920,"end":928.8,"text":"I will talk about how to enjoy the process of learning English even when it's slow,","words":[["I",920],["will",920.32],["talk",920.56],["about",920.8],["how",921.68],["to",922],["enjoy",922.24],["the",922.8],["process",923.28],["of",923.76],["learning",924.08],["English",924.72],["even",926.16],["when",926.56],["it's",927.2],["slow,",927.6]],"ipa":"/aɪ wɪl tɔk əˈbaʊt haʊ tu ˌɛnˈdʒɔɪ ðə ˈprɑˌsɛs ʌv ˈlɝnɪŋ ˈɪŋɡlɪʃ ˈivɪn wɛn ɪts sloʊ/","vi":"Tôi sẽ nói về cách tận hưởng quá trình học tiếng Anh ngay cả khi nó diễn ra chậm,"},{"start":928.8,"end":931.84,"text":"even when it's difficult.","words":[["even",928.8],["when",929.12],["it's",929.76],["difficult.",930.24]],"ipa":"/ˈivɪn wɛn ɪts ˈdɪfəkəlt/","vi":"ngay cả khi điều đó khó khăn."},{"start":931.84,"end":942.56,"text":"Even when you make mistakes, the sentences in this section will continue to be a little longer than before.","words":[["Even",931.84],["when",932.16],["you",932.8],["make",933.12],["mistakes,",933.68],["the",935.92],["sentences",936.16],["in",936.72],["this",936.96],["section",937.2],["will",938.08],["continue",938.56],["to",939.12],["be",939.44],["a",939.76],["little",940.08],["longer",940.64],["than",941.12],["before.",941.36]],"ipa":"/ˈivɪn wɛn ju meɪk mɪˈsteɪks ðə ˈsɛntənsəz ɪn ðɪs ˈsɛkʃən wɪl kənˈtɪnju tu bi ə ˈlɪtəl ˈlɔŋɡər ðæn bɪˈfɔr/","vi":"Ngay cả khi bạn mắc lỗi, các câu trong phần này sẽ tiếp tục dài hơn trước một chút."},{"start":942.56,"end":950.88,"text":"Still easy, still simple, but this will help your listening get stronger. All right.","words":[["Still",942.56],["easy,",942.88],["still",944],["simple,",944.4],["but",945.44],["this",945.68],["will",946],["help",946.24],["your",946.48],["listening",946.8],["get",947.44],["stronger.",948.16],["All",949.28],["right.",949.36]],"ipa":"/stɪl ˈizi stɪl ˈsɪmpəl bʌt ðɪs wɪl hɛlp jɔr ˈlɪsənɪŋ ɡɛt ˈstrɔŋər ɔl raɪt/","vi":"Vẫn dễ, vẫn đơn giản nhưng điều này sẽ giúp khả năng nghe của bạn trở nên mạnh mẽ hơn. Được rồi."},{"start":950.88,"end":955.2,"text":"Learning is a journey, not a race.","words":[["Learning",950.88],["is",951.44],["a",951.76],["journey,",952],["not",952.88],["a",953.28],["race.",953.6]],"ipa":"/ˈlɝnɪŋ ɪz ə ˈdʒɝni nɑt ə reɪs/","vi":"Học tập là một cuộc hành trình, không phải là một cuộc đua."},{"start":955.2,"end":958.48,"text":"You don't need to finish first.","words":[["You",955.2],["don't",955.52],["need",955.84],["to",956.08],["finish",956.4],["first.",957.12]],"ipa":"/ju doʊnt nid tu ˈfɪnɪʃ fɝst/","vi":"Bạn không cần phải hoàn thành trước."},{"start":958.48,"end":962.96,"text":"You don't need to be faster than others.","words":[["You",958.48],["don't",958.8],["need",959.04],["to",959.36],["be",959.6],["faster",959.84],["than",960.8],["others.",961.12]],"ipa":"/ju doʊnt nid tu bi ˈfæstər ðæn ˈʌðərz/","vi":"Bạn không cần phải nhanh hơn người khác."},{"start":962.96,"end":968,"text":"Learning a language is a journey like a long walk.","words":[["Learning",962.96],["a",963.28],["language",963.52],["is",964.16],["a",964.48],["journey",964.72],["like",965.52],["a",965.92],["long",966.16],["walk.",966.64]],"ipa":"/ˈlɝnɪŋ ə ˈlæŋɡwədʒ ɪz ə ˈdʒɝni laɪk ə lɔŋ wɔk/","vi":"Học một ngôn ngữ là một hành trình giống như một chuyến đi bộ dài."},{"start":968,"end":970.64,"text":"You go step by step.","words":[["You",968],["go",968.32],["step",968.64],["by",968.96],["step.",969.28]],"ipa":"/ju ɡoʊ stɛp baɪ stɛp/","vi":"Bạn đi từng bước một."},{"start":970.64,"end":973.36,"text":"You stop and rest.","words":[["You",970.64],["stop",970.96],["and",971.52],["rest.",971.92]],"ipa":"/ju stɑp ənd rɛst/","vi":"Bạn dừng lại và nghỉ ngơi."},{"start":973.36,"end":976,"text":"Sometimes you go fast.","words":[["Sometimes",973.36],["you",973.92],["go",974.24],["fast.",974.48]],"ipa":"/səmˈtaɪmz ju ɡoʊ fæst/","vi":"Đôi khi bạn đi nhanh."},{"start":976,"end":978.64,"text":"Sometimes you go slow.","words":[["Sometimes",976],["you",976.8],["go",977.12],["slow.",977.84]],"ipa":"/səmˈtaɪmz ju ɡoʊ sloʊ/","vi":"Đôi khi bạn đi chậm."},{"start":978.64,"end":980,"text":"And that's okay.","words":[["And",978.64],["that's",978.88],["okay.",979.2]],"ipa":"/ənd ðæts ˌoʊˈkeɪ/","vi":"Và điều đó không sao cả."},{"start":980,"end":982.8,"text":"You don't need to rush.","words":[["You",980],["don't",980.24],["need",980.72],["to",981.04],["rush.",981.28]],"ipa":"/ju doʊnt nid tu rʌʃ/","vi":"Bạn không cần phải vội vàng."},{"start":982.8,"end":986.88,"text":"You just need to continue.","words":[["You",982.8],["just",983.04],["need",983.6],["to",983.92],["continue.",984.56]],"ipa":"/ju dʒʌst nid tu kənˈtɪnju/","vi":"Bạn chỉ cần tiếp tục."},{"start":986.88,"end":990.56,"text":"Remember, there is joy in learning.","words":[["Remember,",986.88],["there",988.16],["is",988.4],["joy",988.88],["in",989.52],["learning.",989.84]],"ipa":"/rɪˈmɛmbər ðɛr ɪz dʒɔɪ ɪn ˈlɝnɪŋ/","vi":"Hãy nhớ rằng, có niềm vui trong học tập."},{"start":990.56,"end":996.24,"text":"There is joy in small wins, in small victories.","words":[["There",990.56],["is",990.72],["joy",991.12],["in",991.76],["small",992.16],["wins,",992.56],["in",993.52],["small",993.84],["victories.",994.64]],"ipa":"/ðɛr ɪz dʒɔɪ ɪn smɔl wɪnz ɪn smɔl ˈvɪktəriz/","vi":"Có niềm vui trong những chiến thắng nhỏ, trong những chiến thắng nhỏ."},{"start":996.24,"end":1000.56,"text":"Like when you understand one sentence in a movie.","words":[["Like",996.24],["when",996.56],["you",996.8],["understand",997.04],["one",997.68],["sentence",998.08],["in",998.4],["a",998.64],["movie.",998.88]],"ipa":"/laɪk wɛn ju ˌʌndərˈstænd wʌn ˈsɛntəns ɪn ə ˈmuvi/","vi":"Giống như khi bạn hiểu được một câu trong một bộ phim."},{"start":1000.56,"end":1006.4,"text":"Like when you speak to someone even for 10 seconds in English.","words":[["Like",1000.56],["when",1000.8],["you",1001.04],["speak",1001.28],["to",1001.52],["someone",1001.84],["even",1002.48],["for",1002.8],["10",1003.2],["seconds",1003.52],["in",1004.08],["English.",1004.4]],"ipa":"/laɪk wɛn ju spik tu ˈsʌmˌwʌn ˈivɪn fɔr ˈsɛkəndz ɪn ˈɪŋɡlɪʃ/","vi":"Giống như khi bạn nói chuyện với ai đó dù chỉ 10 giây bằng tiếng Anh."},{"start":1006.4,"end":1011.52,"text":"Like when you remember a word you learned last week.","words":[["Like",1006.4],["when",1006.64],["you",1006.96],["remember",1007.2],["a",1007.68],["word",1008.08],["you",1008.72],["learned",1009.04],["last",1009.6],["week.",1010]],"ipa":"/laɪk wɛn ju rɪˈmɛmbər ə wɝd ju lɝnd læst wik/","vi":"Giống như khi bạn nhớ lại một từ bạn đã học tuần trước."},{"start":1011.52,"end":1015.84,"text":"These are small, but they feel good.","words":[["These",1011.52],["are",1011.92],["small,",1012.16],["but",1013.44],["they",1013.76],["feel",1014.16],["good.",1014.8]],"ipa":"/ðiz ɑr smɔl bʌt ðeɪ fil ɡʊd/","vi":"Đây là những điều nhỏ, nhưng họ cảm thấy tốt."},{"start":1015.84,"end":1020.08,"text":"You don't need a test to tell you you're doing well.","words":[["You",1015.84],["don't",1016.08],["need",1016.48],["a",1016.72],["test",1016.96],["to",1017.6],["tell",1017.92],["you",1018.08],["you're",1018.56],["doing",1018.96],["well.",1019.28]],"ipa":"/ju doʊnt nid ə tɛst tu tɛl ju jʊr ˈduɪŋ wɛl/","vi":"Bạn không cần một bài kiểm tra để biết bạn đang làm tốt."},{"start":1020.08,"end":1023.44,"text":"You can feel it in your own heart.","words":[["You",1020.08],["can",1020.32],["feel",1020.56],["it",1020.88],["in",1021.28],["your",1021.6],["own",1021.84],["heart.",1022.24]],"ipa":"/ju kæn fil ɪt ɪn jɔr oʊn hɑrt/","vi":"Bạn có thể cảm nhận được điều đó trong chính trái tim mình."},{"start":1023.44,"end":1028.48,"text":"Now, many learners are afraid of making mistakes.","words":[["Now,",1023.44],["many",1024],["learners",1024.32],["are",1024.96],["afraid",1025.28],["of",1025.92],["making",1026.4],["mistakes.",1026.88]],"ipa":"/naʊ ˈmɛni ˈlɝnərz ɑr əˈfreɪd ʌv ˈmeɪkɪŋ mɪˈsteɪks/","vi":"Hiện nay, nhiều người học sợ mắc lỗi."},{"start":1028.48,"end":1041.92,"text":"They say, \\"Tom, I don't want to speak because I might say it wrong or I feel nervous because my grammar is not perfect.\\"","words":[["They",1028.48],["say,",1028.8],["\\"Tom,",1029.36],["I",1030.72],["don't",1031.04],["want",1031.2],["to",1031.44],["speak",1031.68],["because",1032],["I",1033.04],["might",1033.36],["say",1033.68],["it",1033.92],["wrong",1034.16],["or",1035.52],["I",1036.72],["feel",1037.04],["nervous",1037.36],["because",1038.08],["my",1038.56],["grammar",1038.88],["is",1039.52],["not",1039.84],["perfect.\\"",1040.56]],"ipa":"/ðeɪ seɪ tɑm aɪ doʊnt wɑnt tu spik bɪˈkɔz aɪ maɪt seɪ ɪt rɔŋ ɔr aɪ fil ˈnɝvəs bɪˈkɔz maɪ ˈɡræmər ɪz nɑt pərˈfɛkt/","vi":"Họ nói, \\"Tom, tôi không muốn nói vì tôi có thể nói sai hoặc tôi cảm thấy lo lắng vì ngữ pháp của mình không hoàn hảo.\\""},{"start":1041.92,"end":1044.56,"text":"But listen carefully, my friend.","words":[["But",1041.92],["listen",1042.16],["carefully,",1042.48],["my",1043.04],["friend.",1043.28]],"ipa":"/bʌt ˈlɪsən ˈkɛrfəli maɪ frɛnd/","vi":"Nhưng hãy lắng nghe cẩn thận, bạn của tôi."},{"start":1044.56,"end":1048.32,"text":"Mistakes are part of learning.","words":[["Mistakes",1044.56],["are",1045.92],["part",1046.24],["of",1046.64],["learning.",1047.2]],"ipa":"/mɪˈsteɪks ɑr pɑrt ʌv ˈlɝnɪŋ/","vi":"Sai lầm là một phần của việc học hỏi."},{"start":1048.32,"end":1052.64,"text":"In fact, mistakes are how you grow.","words":[["In",1048.32],["fact,",1048.56],["mistakes",1049.28],["are",1050],["how",1050.4],["you",1050.8],["grow.",1051.2]],"ipa":"/ɪn fækt mɪˈsteɪks ɑr haʊ ju ɡroʊ/","vi":"Thực tế, sai lầm chính là cách bạn trưởng thành."},{"start":1052.64,"end":1057.76,"text":"When a baby learns to walk, it falls many times.","words":[["When",1052.64],["a",1052.88],["baby",1053.2],["learns",1053.76],["to",1054.24],["walk,",1054.48],["it",1055.52],["falls",1055.76],["many",1056.24],["times.",1056.64]],"ipa":"/wɛn ə ˈbeɪbi lɝnz tu wɔk ɪt fɔlz ˈmɛni taɪmz/","vi":"Khi bé tập đi, bé sẽ bị ngã nhiều lần."},{"start":1057.76,"end":1060.72,"text":"But nobody says don't try.","words":[["But",1057.76],["nobody",1057.92],["says",1058.4],["don't",1059.04],["try.",1059.36]],"ipa":"/bʌt ˈnoʊˌbɑˌdi sɛz doʊnt traɪ/","vi":"Nhưng không ai nói đừng thử."},{"start":1060.72,"end":1064.08,"text":"We smile and say, \\"Try again.\\"","words":[["We",1060.72],["smile",1061.12],["and",1061.44],["say,",1061.84],["\\"Try",1062.48],["again.\\"",1063.04]],"ipa":"/wi smaɪl ənd seɪ traɪ əˈɡɛn/","vi":"Chúng tôi mỉm cười và nói: \\"Hãy thử lại.\\""},{"start":1064.08,"end":1069.04,"text":"And that's how the baby learns to walk.","words":[["And",1064.08],["that's",1064.32],["how",1064.8],["the",1065.04],["baby",1065.36],["learns",1066.24],["to",1066.88],["walk.",1067.2]],"ipa":"/ənd ðæts haʊ ðə ˈbeɪbi lɝnz tu wɔk/","vi":"Và đó là cách em bé tập đi."},{"start":1069.04,"end":1072.64,"text":"You are doing the same just with English.","words":[["You",1069.04],["are",1069.36],["doing",1069.52],["the",1069.76],["same",1070.08],["just",1070.64],["with",1070.96],["English.",1071.28]],"ipa":"/ju ɑr ˈduɪŋ ðə seɪm dʒʌst wɪð ˈɪŋɡlɪʃ/","vi":"Bạn đang làm điều tương tự chỉ với tiếng Anh."},{"start":1072.64,"end":1074.8,"text":"You are walking.","words":[["You",1072.64],["are",1072.96],["walking.",1073.2]],"ipa":"/ju ɑr ˈwɔkɪŋ/","vi":"Bạn đang đi bộ."},{"start":1074.8,"end":1076.72,"text":"You are trying.","words":[["You",1074.8],["are",1074.96],["trying.",1075.2]],"ipa":"/ju ɑr ˈtraɪɪŋ/","vi":"Bạn đang cố gắng."},{"start":1076.72,"end":1078.4,"text":"You are learning.","words":[["You",1076.72],["are",1076.96],["learning.",1077.2]],"ipa":"/ju ɑr ˈlɝnɪŋ/","vi":"Bạn đang học."},{"start":1078.4,"end":1082.96,"text":"So if you say the wrong word, it's okay.","words":[["So",1078.4],["if",1078.8],["you",1079.04],["say",1079.28],["the",1079.44],["wrong",1079.76],["word,",1080.08],["it's",1081.04],["okay.",1081.36]],"ipa":"/soʊ ɪf ju seɪ ðə rɔŋ wɝd ɪts ˌoʊˈkeɪ/","vi":"Vì thế nếu bạn nói sai từ nào cũng không sao."},{"start":1082.96,"end":1087.36,"text":"If you forget something, it's okay.","words":[["If",1082.96],["you",1083.2],["forget",1083.44],["something,",1083.92],["it's",1085.12],["okay.",1085.68]],"ipa":"/ɪf ju fərˈɡɛt ˈsʌmθɪŋ ɪts ˌoʊˈkeɪ/","vi":"Nếu bạn quên điều gì đó thì không sao cả."},{"start":1087.36,"end":1092.32,"text":"If someone corrects you, it's totally okay.","words":[["If",1087.36],["someone",1087.68],["corrects",1088.24],["you,",1088.72],["it's",1089.52],["totally",1090.08],["okay.",1090.8]],"ipa":"/ɪf ˈsʌmˌwʌn kərˈɛkts ju ɪts ˈtoʊtəli ˌoʊˈkeɪ/","vi":"Nếu có ai đó sửa lỗi cho bạn thì điều đó hoàn toàn không sao cả."},{"start":1092.32,"end":1094.96,"text":"That means you are learning.","words":[["That",1092.32],["means",1092.56],["you",1093.04],["are",1093.36],["learning.",1093.84]],"ipa":"/ðæt minz ju ɑr ˈlɝnɪŋ/","vi":"Điều đó có nghĩa là bạn đang học."},{"start":1094.96,"end":1098.72,"text":"No one speaks perfectly all the time.","words":[["No",1094.96],["one",1095.2],["speaks",1095.44],["perfectly",1096],["all",1096.8],["the",1097.12],["time.",1097.36]],"ipa":"/noʊ wʌn spiks ˈpɝfəktli ɔl ðə taɪm/","vi":"Không ai có thể nói chuyện một cách hoàn hảo mọi lúc."},{"start":1098.72,"end":1102.24,"text":"Even native speakers make mistakes.","words":[["Even",1098.72],["native",1099.2],["speakers",1099.76],["make",1100.72],["mistakes.",1101.04]],"ipa":"/ˈivɪn ˈneɪtɪv ˈspikərz meɪk mɪˈsteɪks/","vi":"Ngay cả người bản ngữ cũng mắc lỗi."},{"start":1102.24,"end":1105.52,"text":"So please don't be afraid.","words":[["So",1102.24],["please",1103.12],["don't",1103.68],["be",1104],["afraid.",1104.16]],"ipa":"/soʊ pliz doʊnt bi əˈfreɪd/","vi":"Vì vậy xin đừng sợ hãi."},{"start":1105.52,"end":1110.24,"text":"Speak anyway, write anyway, practice anyway.","words":[["Speak",1105.52],["anyway,",1105.84],["write",1107.04],["anyway,",1107.44],["practice",1108.56],["anyway.",1109.12]],"ipa":"/spik ˈɛniˌweɪ raɪt ˈɛniˌweɪ ˈpræktəs ˈɛniˌweɪ/","vi":"Nói thế nào, viết thế nào, luyện tập thế nào."},{"start":1110.24,"end":1112.96,"text":"You just need to be brave.","words":[["You",1110.24],["just",1110.48],["need",1110.96],["to",1111.12],["be",1111.36],["brave.",1111.6]],"ipa":"/ju dʒʌst nid tu bi breɪv/","vi":"Bạn chỉ cần dũng cảm."},{"start":1112.96,"end":1118,"text":"You don't always need to study in a serious way.","words":[["You",1112.96],["don't",1113.2],["always",1113.6],["need",1114.4],["to",1114.64],["study",1114.96],["in",1115.52],["a",1115.76],["serious",1116],["way.",1116.56]],"ipa":"/ju doʊnt ˈɔlˌweɪz nid tu ˈstʌdi ɪn ə ˈsɪriəs weɪ/","vi":"Không phải lúc nào bạn cũng cần học một cách nghiêm túc."},{"start":1118,"end":1121.12,"text":"You can make learning fun.","words":[["You",1118],["can",1118.24],["make",1118.48],["learning",1118.8],["fun.",1119.76]],"ipa":"/ju kæn meɪk ˈlɝnɪŋ fʌn/","vi":"Bạn có thể làm cho việc học trở nên thú vị."},{"start":1121.12,"end":1124.48,"text":"You can listen to music in English.","words":[["You",1121.12],["can",1121.36],["listen",1121.6],["to",1121.92],["music",1122.24],["in",1122.8],["English.",1123.12]],"ipa":"/ju kæn ˈlɪsən tu ˈmjuzɪk ɪn ˈɪŋɡlɪʃ/","vi":"Bạn có thể nghe nhạc bằng tiếng Anh."},{"start":1124.48,"end":1127.92,"text":"You can watch short videos.","words":[["You",1124.48],["can",1124.72],["watch",1124.96],["short",1125.6],["videos.",1126.16]],"ipa":"/ju kæn wɑtʃ ʃɔrt ˈvɪdioʊz/","vi":"Bạn có thể xem video ngắn."},{"start":1127.92,"end":1131.44,"text":"You can speak to yourself in the mirror.","words":[["You",1127.92],["can",1128.16],["speak",1128.4],["to",1128.64],["yourself",1128.96],["in",1129.68],["the",1129.92],["mirror.",1130.08]],"ipa":"/ju kæn spik tu jərˈsɛlf ɪn ðə ˈmɪrər/","vi":"Bạn có thể nói chuyện với chính mình trong gương."},{"start":1131.44,"end":1137.52,"text":"You can read something interesting, not just textbooks.","words":[["You",1131.44],["can",1131.76],["read",1132],["something",1132.48],["interesting,",1133.28],["not",1134.56],["just",1134.8],["textbooks.",1135.36]],"ipa":"/ju kæn rɛd ˈsʌmθɪŋ ˈɪntrəstɪŋ nɑt dʒʌst ˈtɛkstˌbʊks/","vi":"Bạn có thể đọc một cái gì đó thú vị, không chỉ sách giáo khoa."},{"start":1137.52,"end":1141.84,"text":"Learning can be a part of your daily life.","words":[["Learning",1137.52],["can",1138.32],["be",1138.64],["a",1138.88],["part",1139.2],["of",1139.44],["your",1139.76],["daily",1140.08],["life.",1140.56]],"ipa":"/ˈlɝnɪŋ kæn bi ə pɑrt ʌv jɔr ˈdeɪli laɪf/","vi":"Học tập có thể là một phần của cuộc sống hàng ngày của bạn."},{"start":1141.84,"end":1146.8,"text":"It can feel like play, not pressure.","words":[["It",1141.84],["can",1142.08],["feel",1142.4],["like",1142.64],["play,",1143.36],["not",1144.4],["pressure.",1145.12]],"ipa":"/ɪt kæn fil laɪk pleɪ nɑt ˈprɛʃər/","vi":"Nó có thể giống như chơi đùa, không phải áp lực."},{"start":1146.8,"end":1150.72,"text":"When you enjoy learning, you learn more.","words":[["When",1146.8],["you",1147.04],["enjoy",1147.28],["learning,",1147.68],["you",1148.56],["learn",1148.8],["more.",1149.44]],"ipa":"/wɛn ju ˌɛnˈdʒɔɪ ˈlɝnɪŋ ju lɝn mɔr/","vi":"Khi bạn thích học, bạn sẽ học được nhiều hơn."},{"start":1150.72,"end":1158,"text":"When you smile while studying, your brain remembers better.","words":[["When",1150.72],["you",1150.96],["smile",1151.28],["while",1152.08],["studying,",1152.48],["your",1153.84],["brain",1154.24],["remembers",1155.2],["better.",1156.24]],"ipa":"/wɛn ju smaɪl waɪl ˈstʌdiɪŋ jɔr breɪn rɪˈmɛmbərz ˈbɛtər/","vi":"Khi bạn mỉm cười trong khi học, não bạn sẽ ghi nhớ tốt hơn."},{"start":1158,"end":1164.16,"text":"So find what you love and do it in English. All right.","words":[["So",1158],["find",1159.04],["what",1159.76],["you",1160],["love",1160.32],["and",1160.8],["do",1161.2],["it",1161.44],["in",1161.92],["English.",1162.24],["All right.",1163.12]],"ipa":"/soʊ faɪnd wʌt ju lʌv ənd du ɪt ɪn ˈɪŋɡlɪʃ All right/","vi":"Vì vậy, hãy tìm những gì bạn yêu thích và làm nó bằng tiếng Anh. Được rồi."},{"start":1164.16,"end":1174.4,"text":"In this part of the episode, I want to talk to you about something important. Your future.","words":[["In",1164.16],["this",1164.4],["part",1164.64],["of",1164.88],["the",1165.04],["episode,",1165.36],["I",1166.64],["want",1166.96],["to",1167.2],["talk",1167.44],["to",1167.68],["you",1167.92],["about",1168.24],["something",1168.72],["important.",1169.44],["Your",1171.12],["future.",1172.32]],"ipa":"/ɪn ðɪs pɑrt ʌv ðə ˈɛpəˌsoʊd aɪ wɑnt tu tɔk tu ju əˈbaʊt ˈsʌmθɪŋ ˌɪmˈpɔrtənt jɔr ˈfjutʃər/","vi":"Trong phần này của tập phim, tôi muốn nói với bạn về một điều quan trọng. Tương lai của bạn."},{"start":1174.4,"end":1182.08,"text":"I want to show you how learning English even slowly, even in small steps,","words":[["I",1174.4],["want",1174.72],["to",1174.88],["show",1175.12],["you",1175.28],["how",1175.84],["learning",1176.16],["English",1176.64],["even",1177.52],["slowly,",1178.08],["even",1179.36],["in",1179.92],["small",1180.32],["steps,",1180.8]],"ipa":"/aɪ wɑnt tu ʃoʊ ju haʊ ˈlɝnɪŋ ˈɪŋɡlɪʃ ˈivɪn ˈsloʊli ˈivɪn ɪn smɔl stɛps/","vi":"Tôi muốn chỉ cho bạn cách học tiếng Anh chậm rãi, thậm chí từng bước nhỏ,"},{"start":1182.08,"end":1185.6,"text":"can open new doors in your life.","words":[["can",1182.08],["open",1182.48],["new",1182.96],["doors",1183.36],["in",1184.16],["your",1184.48],["life.",1184.8]],"ipa":"/kæn ˈoʊpən nu dɔrz ɪn jɔr laɪf/","vi":"có thể mở ra những cánh cửa mới trong cuộc đời bạn."},{"start":1185.6,"end":1188.88,"text":"English is not just a subject.","words":[["English",1185.6],["is",1186.32],["not",1186.64],["just",1187.12],["a",1187.44],["subject.",1187.76]],"ipa":"/ˈɪŋɡlɪʃ ɪz nɑt dʒʌst ə səbˈdʒɛkt/","vi":"Tiếng Anh không chỉ là một môn học."},{"start":1188.88,"end":1191.52,"text":"It's not just a class you take.","words":[["It's",1188.88],["not",1189.12],["just",1189.36],["a",1189.6],["class",1189.92],["you",1190.32],["take.",1190.64]],"ipa":"/ɪts nɑt dʒʌst ə klæs ju teɪk/","vi":"Đó không chỉ là một lớp học bạn tham gia."},{"start":1191.52,"end":1193.04,"text":"It's a tool.","words":[["It's",1191.52],["a",1191.76],["tool.",1192]],"ipa":"/ɪts ə tul/","vi":"Đó là một công cụ."},{"start":1193.04,"end":1195.04,"text":"It's a key.","words":[["It's",1193.04],["a",1193.36],["key.",1193.68]],"ipa":"/ɪts ə ki/","vi":"Đó là một chiếc chìa khóa."},{"start":1195.04,"end":1200.4,"text":"It's something you can use in real life everywhere.","words":[["It's",1195.04],["something",1195.36],["you",1195.76],["can",1196.08],["use",1196.32],["in",1196.8],["real",1197.2],["life",1197.6],["everywhere.",1198.72]],"ipa":"/ɪts ˈsʌmθɪŋ ju kæn jus ɪn ril laɪf ˈɛvriˌwɛr/","vi":"Đó là thứ bạn có thể sử dụng trong cuộc sống thực ở mọi nơi."},{"start":1200.4,"end":1206.32,"text":"When you learn English, you can talk to people from different countries.","words":[["When",1200.4],["you",1200.64],["learn",1200.88],["English,",1201.2],["you",1202],["can",1202.32],["talk",1202.56],["to",1202.88],["people",1203.12],["from",1204],["different",1204.48],["countries.",1204.96]],"ipa":"/wɛn ju lɝn ˈɪŋɡlɪʃ ju kæn tɔk tu ˈpipəl frʌm ˈdɪfərənt ˈkʌntriz/","vi":"Khi bạn học tiếng Anh, bạn có thể nói chuyện với mọi người từ các quốc gia khác nhau."},{"start":1206.32,"end":1209.52,"text":"You can make new friends online.","words":[["You",1206.32],["can",1206.56],["make",1206.8],["new",1207.44],["friends",1207.76],["online.",1208.48]],"ipa":"/ju kæn meɪk nu frɛndz ˈɔnˌlaɪn/","vi":"Bạn có thể kết bạn mới trực tuyến."},{"start":1209.52,"end":1216.8,"text":"You can understand movies, books, musics and news in English.","words":[["You",1209.52],["can",1209.76],["understand",1210],["movies,",1210.8],["books,",1212.08],["musics",1213.44],["and",1214.32],["news",1214.64],["in",1215.28],["English.",1215.52]],"ipa":"/ju kæn ˌʌndərˈstænd ˈmuviz bʊks ˈmjuzɪks ənd nuz ɪn ˈɪŋɡlɪʃ/","vi":"Bạn có thể hiểu phim, sách, nhạc và tin tức bằng tiếng Anh."},{"start":1216.8,"end":1222.56,"text":"You can join conversations, not just listen from the side.","words":[["You",1216.8],["can",1217.04],["join",1217.28],["conversations,",1217.92],["not",1219.44],["just",1219.76],["listen",1220.08],["from",1220.88],["the",1221.2],["side.",1221.44]],"ipa":"/ju kæn dʒɔɪn ˌkɑnvərˈseɪʃənz nɑt dʒʌst ˈlɪsən frʌm ðə saɪd/","vi":"Bạn có thể tham gia các cuộc trò chuyện chứ không chỉ nghe từ bên cạnh."},{"start":1222.56,"end":1226.48,"text":"You can be part of the global world.","words":[["You",1222.56],["can",1222.8],["be",1222.96],["part",1223.28],["of",1223.6],["the",1223.84],["global",1224.32],["world.",1224.96]],"ipa":"/ju kæn bi pɑrt ʌv ðə ˈɡloʊbəl wɝld/","vi":"Bạn có thể là một phần của thế giới toàn cầu."},{"start":1226.48,"end":1228.32,"text":"Think about it.","words":[["Think",1226.48],["about",1226.8],["it.",1226.96]],"ipa":"/θɪŋk əˈbaʊt ɪt/","vi":"Hãy nghĩ về nó."},{"start":1228.32,"end":1234.32,"text":"More than 1.5 billion people speak English today.","words":[["More",1228.32],["than",1228.64],["1.5",1229.2],["billion",1230.56],["people",1231.12],["speak",1232.08],["English",1232.56],["today.",1233.12]],"ipa":"/mɔr ðæn ˈbɪljən ˈpipəl spik ˈɪŋɡlɪʃ təˈdeɪ/","vi":"Ngày nay có hơn 1,5 tỷ người nói tiếng Anh."},{"start":1234.32,"end":1240.96,"text":"That means when you speak English, you are never truly alone.","words":[["That",1234.32],["means",1234.64],["when",1235.36],["you",1235.6],["speak",1235.84],["English,",1236.16],["you",1237.04],["are",1237.28],["never",1237.92],["truly",1238.56],["alone.",1239.12]],"ipa":"/ðæt minz wɛn ju spik ˈɪŋɡlɪʃ ju ɑr ˈnɛvər ˈtruli əˈloʊn/","vi":"Điều đó có nghĩa là khi bạn nói tiếng Anh, bạn không bao giờ thực sự cô đơn."},{"start":1240.96,"end":1251.12,"text":"No matter where you live, Brazil, Vietnam, Iran, Spain, Iraq, Ukraine, Russia, South Korea,","words":[["No",1240.96],["matter",1241.04],["where",1241.52],["you",1241.84],["live,",1242],["Brazil,",1242.96],["Vietnam,",1243.92],["Iran,",1245.04],["Spain,",1246.08],["Iraq,",1247.04],["Ukraine,",1248.08],["Russia,",1249.2],["South",1250.08],["Korea,",1250.4]],"ipa":"/noʊ ˈmætər wɛr ju laɪv brəˈzɪl viˌɛtˈnɑm ˌɪˈrɑn speɪn ˌɪˈrɑk juˈkreɪn ˈrʌʃə saʊθ ˌkɔˈriə/","vi":"Bất kể bạn sống ở đâu, Brazil, Việt Nam, Iran, Tây Ban Nha, Iraq, Ukraine, Nga, Hàn Quốc,"},{"start":1251.12,"end":1260.96,"text":"Japan, Indonesia, Thailand, English can connect you to someone on the other side of the world.","words":[["Japan,",1251.12],["Indonesia,",1252.16],["Thailand,",1253.28],["English",1254.88],["can",1255.92],["connect",1256.32],["you",1256.72],["to",1257.28],["someone",1257.68],["on",1258.24],["the",1258.56],["other",1258.8],["side",1259.2],["of",1259.68],["the",1259.92],["world.",1260.16]],"ipa":"/dʒəˈpæn ˌɪndoʊˈniʒə ˈtaɪˌlænd ˈɪŋɡlɪʃ kæn kəˈnɛkt ju tu ˈsʌmˌwʌn ɑn ðə ˈʌðər saɪd ʌv ðə wɝld/","vi":"Nhật Bản, Indonesia, Thái Lan, tiếng Anh có thể kết nối bạn với ai đó ở bên kia thế giới."},{"start":1260.96,"end":1267.36,"text":"It gives you a way to understand people and a way to be understood.","words":[["It",1260.96],["gives",1261.28],["you",1261.52],["a",1261.76],["way",1262],["to",1262.4],["understand",1262.72],["people",1263.36],["and",1264.64],["a",1264.88],["way",1265.12],["to",1265.52],["be",1265.84],["understood.",1266.08]],"ipa":"/ɪt ɡɪvz ju ə weɪ tu ˌʌndərˈstænd ˈpipəl ənd ə weɪ tu bi ˌʌndərˈstʊd/","vi":"Nó cho bạn một cách để hiểu mọi người và một cách để được hiểu."},{"start":1267.36,"end":1270.88,"text":"That, my friend, is powerful.","words":[["That,",1267.36],["my",1267.76],["friend,",1268],["is",1268.96],["powerful.",1269.76]],"ipa":"/ðæt maɪ frɛnd ɪz ˈpaʊərfəl/","vi":"Điều đó, bạn của tôi, thật mạnh mẽ."},{"start":1270.88,"end":1274.56,"text":"English gives you more choices.","words":[["English",1270.88],["gives",1271.44],["you",1271.76],["more",1272.08],["choices.",1272.56]],"ipa":"/ˈɪŋɡlɪʃ ɡɪvz ju mɔr ˈtʃɔɪsəz/","vi":"Tiếng Anh mang lại cho bạn nhiều sự lựa chọn hơn."},{"start":1274.56,"end":1278.56,"text":"Maybe you want to get a better job.","words":[["Maybe",1274.56],["you",1275.04],["want",1275.36],["to",1275.6],["get",1275.84],["a",1276.16],["better",1276.4],["job.",1276.8]],"ipa":"/ˈmeɪbi ju wɑnt tu ɡɛt ə ˈbɛtər dʒɑb/","vi":"Có lẽ bạn muốn có được một công việc tốt hơn."},{"start":1278.56,"end":1282.96,"text":"Maybe you want to study in another country.","words":[["Maybe",1278.56],["you",1279.04],["want",1279.36],["to",1279.6],["study",1279.84],["in",1280.32],["another",1280.88],["country.",1281.52]],"ipa":"/ˈmeɪbi ju wɑnt tu ˈstʌdi ɪn əˈnʌðər ˈkʌntri/","vi":"Có lẽ bạn muốn học ở một đất nước khác."},{"start":1282.96,"end":1287.36,"text":"Maybe you want to travel or work abroad.","words":[["Maybe",1282.96],["you",1283.52],["want",1283.84],["to",1284],["travel",1284.24],["or",1284.96],["work",1285.28],["abroad.",1285.76]],"ipa":"/ˈmeɪbi ju wɑnt tu ˈtrævəl ɔr wɝk əˈbrɔd/","vi":"Có thể bạn muốn đi du lịch hoặc làm việc ở nước ngoài."},{"start":1287.36,"end":1291.28,"text":"English makes those dreams easier.","words":[["English",1287.36],["makes",1288.4],["those",1288.96],["dreams",1289.44],["easier.",1290.4]],"ipa":"/ˈɪŋɡlɪʃ meɪks ðoʊz drimz ˈiziər/","vi":"Tiếng Anh khiến những giấc mơ đó trở nên dễ dàng hơn."},{"start":1291.28,"end":1296.72,"text":"When you speak English, you can apply for international jobs.","words":[["When",1291.28],["you",1291.52],["speak",1291.76],["English,",1292.08],["you",1292.8],["can",1293.12],["apply",1293.36],["for",1293.92],["international",1294.48],["jobs.",1295.36]],"ipa":"/wɛn ju spik ˈɪŋɡlɪʃ ju kæn əˈplaɪ fɔr ˌɪntərˈnæʃənəl dʒɑbz/","vi":"Khi bạn nói tiếng Anh, bạn có thể xin việc làm quốc tế."},{"start":1296.72,"end":1303.68,"text":"You can understand what's happening in the world, not just your own city.","words":[["You",1296.72],["can",1296.96],["understand",1297.28],["what's",1298.24],["happening",1298.72],["in",1299.28],["the",1299.52],["world,",1299.76],["not",1300.64],["just",1300.96],["your",1301.44],["own",1301.84],["city.",1302.24]],"ipa":"/ju kæn ˌʌndərˈstænd wʌts ˈhæpənɪŋ ɪn ðə wɝld nɑt dʒʌst jɔr oʊn ˈsɪti/","vi":"Bạn có thể hiểu những gì đang xảy ra trên thế giới, không chỉ thành phố của bạn."},{"start":1303.68,"end":1307.36,"text":"Even in your own country, English helps.","words":[["Even",1303.68],["in",1304.24],["your",1304.56],["own",1304.8],["country,",1305.04],["English",1305.84],["helps.",1306.24]],"ipa":"/ˈivɪn ɪn jɔr oʊn ˈkʌntri ˈɪŋɡlɪʃ hɛlps/","vi":"Ngay cả ở đất nước của bạn, tiếng Anh cũng có ích."},{"start":1307.36,"end":1313.2,"text":"More and more companies look for people who can speak English.","words":[["More",1307.36],["and",1307.6],["more",1307.92],["companies",1308.32],["look",1309.2],["for",1309.44],["people",1309.76],["who",1310.48],["can",1310.8],["speak",1311.12],["English.",1311.6]],"ipa":"/mɔr ənd mɔr ˈkʌmpəˌniz lʊk fɔr ˈpipəl hu kæn spik ˈɪŋɡlɪʃ/","vi":"Ngày càng có nhiều công ty tìm kiếm những người có thể nói tiếng Anh."},{"start":1313.2,"end":1318.64,"text":"more websites, tools and machines use English.","words":[["more",1313.2],["websites,",1313.68],["tools",1314.8],["and",1315.52],["machines",1315.92],["use",1316.88],["English.",1317.36]],"ipa":"/mɔr ˈwɛbˌsaɪts tulz ənd məˈʃinz jus ˈɪŋɡlɪʃ/","vi":"nhiều trang web, công cụ và máy móc sử dụng tiếng Anh hơn."},{"start":1318.64,"end":1331.92,"text":"So when you learn English, you are learning something useful, something practical, something that gives you more freedom and opportunity.","words":[["So",1318.64],["when",1319.04],["you",1319.36],["learn",1319.6],["English,",1319.92],["you",1320.72],["are",1321.04],["learning",1321.28],["something",1321.68],["useful,",1322.48],["something",1323.76],["practical,",1324.48],["something",1326.56],["that",1326.96],["gives",1327.36],["you",1327.68],["more",1328],["freedom",1328.48],["and",1329.44],["opportunity.",1330.32]],"ipa":"/soʊ wɛn ju lɝn ˈɪŋɡlɪʃ ju ɑr ˈlɝnɪŋ ˈsʌmθɪŋ ˈjusfəl ˈsʌmθɪŋ ˈpræktəkəl ˈsʌmθɪŋ ðæt ɡɪvz ju mɔr ˈfridəm ənd ˌɑpərˈtunəti/","vi":"Vì vậy, khi bạn học tiếng Anh, bạn đang học điều gì đó hữu ích, điều gì đó thiết thực, điều gì đó mang lại cho bạn nhiều tự do và cơ hội hơn."},{"start":1331.92,"end":1337.12,"text":"All right, you have made it to the end of this episode.","words":[["All",1331.92],["right,",1332],["you",1333.04],["have",1333.36],["made",1333.68],["it",1333.92],["to",1334.32],["the",1334.56],["end",1334.8],["of",1335.04],["this",1335.28],["episode.",1335.76]],"ipa":"/ɔl raɪt ju hæv meɪd ɪt tu ðə ɛnd ʌv ðɪs ˈɛpəˌsoʊd/","vi":"Được rồi, bạn đã đi đến cuối tập này."},{"start":1337.12,"end":1340,"text":"You listened with your heart.","words":[["You",1337.12],["listened",1337.36],["with",1338],["your",1338.32],["heart.",1338.64]],"ipa":"/ju ˈlɪsənd wɪð jɔr hɑrt/","vi":"Bạn đã lắng nghe bằng trái tim mình."},{"start":1340,"end":1347.04,"text":"You gave your time and your energy to something important, yourself.","words":[["You",1340],["gave",1340.32],["your",1340.64],["time",1340.88],["and",1341.36],["your",1341.68],["energy",1342],["to",1342.88],["something",1343.2],["important,",1343.92],["yourself.",1345.36]],"ipa":"/ju ɡeɪv jɔr taɪm ənd jɔr ˈɛnərdʒi tu ˈsʌmθɪŋ ˌɪmˈpɔrtənt jərˈsɛlf/","vi":"Bạn đã dành thời gian và năng lượng của mình cho một điều gì đó quan trọng, đó là chính bạn."},{"start":1347.04,"end":1350.4,"text":"Today I talked about motivation.","words":[["Today",1347.04],["I",1347.84],["talked",1348.16],["about",1348.48],["motivation.",1349.2]],"ipa":"/təˈdeɪ aɪ tɔkt əˈbaʊt ˌmoʊtəˈveɪʃən/","vi":"Hôm nay tôi đã nói về động lực."},{"start":1350.4,"end":1354.32,"text":"I talked about how learning English takes time.","words":[["I",1350.4],["talked",1350.64],["about",1350.96],["how",1351.44],["learning",1351.84],["English",1352.24],["takes",1352.96],["time.",1353.44]],"ipa":"/aɪ tɔkt əˈbaʊt haʊ ˈlɝnɪŋ ˈɪŋɡlɪʃ teɪks taɪm/","vi":"Tôi đã nói về việc học tiếng Anh cần có thời gian như thế nào."},{"start":1354.32,"end":1357.68,"text":"I talked about how to keep going.","words":[["I",1354.32],["talked",1354.64],["about",1354.96],["how",1355.52],["to",1355.84],["keep",1356.16],["going.",1356.64]],"ipa":"/aɪ tɔkt əˈbaʊt haʊ tu kip ˈɡoʊɪŋ/","vi":"Tôi đã nói về cách tiếp tục."},{"start":1357.68,"end":1364.08,"text":"And finally, I talked about how English can change your life.","words":[["And",1357.68],["finally,",1357.92],["I",1358.8],["talked",1359.12],["about",1359.44],["how",1360],["English",1360.48],["can",1361.44],["change",1361.84],["your",1362.56],["life.",1362.96]],"ipa":"/ənd ˈfaɪnəli aɪ tɔkt əˈbaʊt haʊ ˈɪŋɡlɪʃ kæn tʃeɪndʒ jɔr laɪf/","vi":"Và cuối cùng, tôi đã nói về việc tiếng Anh có thể thay đổi cuộc sống của bạn như thế nào."},{"start":1364.08,"end":1367.2,"text":"And now I want to tell you this.","words":[["And",1364.08],["now",1364.32],["I",1364.8],["want",1365.12],["to",1365.28],["tell",1365.52],["you",1365.68],["this.",1365.84]],"ipa":"/ənd naʊ aɪ wɑnt tu tɛl ju ðɪs/","vi":"Và bây giờ tôi muốn nói với bạn điều này."},{"start":1367.2,"end":1370.08,"text":"I am proud of you.","words":[["I",1367.2],["am",1367.6],["proud",1368.4],["of",1368.72],["you.",1368.96]],"ipa":"/aɪ æm praʊd ʌv ju/","vi":"Tôi tự hào về bạn."},{"start":1370.08,"end":1372.48,"text":"You are doing something difficult.","words":[["You",1370.08],["are",1370.32],["doing",1370.56],["something",1370.88],["difficult.",1371.36]],"ipa":"/ju ɑr ˈduɪŋ ˈsʌmθɪŋ ˈdɪfəkəlt/","vi":"Bạn đang làm một việc gì đó khó khăn."},{"start":1372.48,"end":1377.6,"text":"You are building a skill that can change your future.","words":[["You",1372.48],["are",1372.8],["building",1373.36],["a",1373.76],["skill",1374.08],["that",1374.56],["can",1374.96],["change",1375.28],["your",1376.08],["future.",1376.48]],"ipa":"/ju ɑr ˈbɪldɪŋ ə skɪl ðæt kæn tʃeɪndʒ jɔr ˈfjutʃər/","vi":"Bạn đang xây dựng một kỹ năng có thể thay đổi tương lai của bạn."},{"start":1377.6,"end":1380.48,"text":"It doesn't matter if you speak slowly.","words":[["It",1377.6],["doesn't",1377.92],["matter",1378.16],["if",1378.48],["you",1378.8],["speak",1379.04],["slowly.",1379.6]],"ipa":"/ɪt ˈdʌzənt ˈmætər ɪf ju spik ˈsloʊli/","vi":"Sẽ không có vấn đề gì nếu bạn nói chậm."},{"start":1380.48,"end":1383.76,"text":"It doesn't matter if you make mistakes.","words":[["It",1380.48],["doesn't",1380.8],["matter",1381.04],["if",1381.52],["you",1381.84],["make",1382.08],["mistakes.",1382.48]],"ipa":"/ɪt ˈdʌzənt ˈmætər ɪf ju meɪk mɪˈsteɪks/","vi":"Sẽ không có vấn đề gì nếu bạn phạm sai lầm."},{"start":1383.76,"end":1387.92,"text":"It doesn't matter if you feel nervous or shy.","words":[["It",1383.76],["doesn't",1384],["matter",1384.24],["if",1384.72],["you",1385.04],["feel",1385.28],["nervous",1385.84],["or",1386.48],["shy.",1386.8]],"ipa":"/ɪt ˈdʌzənt ˈmætər ɪf ju fil ˈnɝvəs ɔr ʃaɪ/","vi":"Sẽ không có vấn đề gì nếu bạn cảm thấy lo lắng hay ngại ngùng."},{"start":1387.92,"end":1390.56,"text":"What matters is this.","words":[["What",1387.92],["matters",1388.24],["is",1388.88],["this.",1389.2]],"ipa":"/wʌt ˈmætərz ɪz ðɪs/","vi":"Điều quan trọng là điều này."},{"start":1390.56,"end":1392.96,"text":"You are trying.","words":[["You",1390.56],["are",1390.88],["trying.",1391.52]],"ipa":"/ju ɑr ˈtraɪɪŋ/","vi":"Bạn đang cố gắng."},{"start":1392.96,"end":1395.36,"text":"You are growing.","words":[["You",1392.96],["are",1393.28],["growing.",1393.92]],"ipa":"/ju ɑr ˈɡroʊɪŋ/","vi":"Bạn đang phát triển."},{"start":1395.36,"end":1397.52,"text":"You are showing up.","words":[["You",1395.36],["are",1395.68],["showing",1396.32],["up.",1396.72]],"ipa":"/ju ɑr ˈʃoʊɪŋ ʌp/","vi":"Bạn đang xuất hiện."},{"start":1397.52,"end":1401.92,"text":"I'm Tom and this is English Unleashed.","words":[["I'm",1397.52],["Tom",1397.76],["and",1398.72],["this",1398.96],["is",1399.44],["English",1400.08],["Unleashed.",1400.72]],"ipa":"/aɪm tɑm ənd ðɪs ɪz ˈɪŋɡlɪʃ ənˈliʃt/","vi":"Tôi là Tom và đây là English Unleashed."},{"start":1401.92,"end":1407.6,"text":"Thank you for showing up and thank you for being part of this journey.","words":[["Thank",1401.92],["you",1402.16],["for",1402.32],["showing",1402.64],["up",1402.96],["and",1403.68],["thank",1404.08],["you",1404.32],["for",1405.04],["being",1405.36],["part",1405.76],["of",1406.08],["this",1406.32],["journey.",1406.8]],"ipa":"/θæŋk ju fɔr ˈʃoʊɪŋ ʌp ənd θæŋk ju fɔr ˈbiɪŋ pɑrt ʌv ðɪs ˈdʒɝni/","vi":"Cảm ơn bạn đã xuất hiện và cảm ơn bạn đã là một phần của cuộc hành trình này."},{"start":1407.6,"end":1413.76,"text":"Keep listening, keep speaking and keep believing in yourself.","words":[["Keep",1407.6],["listening,",1407.92],["keep",1408.96],["speaking",1409.28],["and",1410.32],["keep",1410.72],["believing",1411.28],["in",1411.92],["yourself.",1412.24]],"ipa":"/kip ˈlɪsənɪŋ kip ˈspikɪŋ ənd kip bɪˈlivɪŋ ɪn jərˈsɛlf/","vi":"Hãy tiếp tục lắng nghe, tiếp tục nói và tiếp tục tin tưởng vào chính mình."},{"start":1413.76,"end":1417.32,"text":"Bye for now.","words":[["Bye",1413.76],["for",1414.08],["now.",1414.32]],"ipa":"/baɪ fɔr naʊ/","vi":"Tạm biệt nhé."},{"start":1419.68,"end":1422.68,"text":"Heat. Heat. N.","words":[["Heat. Heat. N.",1419.68]],"ipa":"/Heat. Heat. N/","vi":"Nhiệt. Nhiệt. N."}]`),l={id:t,youtubeId:n,title:e,channel:i,level:"A1",group:a,order:2,duration:1435,captions:s,segments:o};export{s as captions,i as channel,l as default,h as duration,a as group,t as id,r as level,d as order,o as segments,e as title,n as youtubeId};
